// Original examples and explanations. Reference links verify mathematical facts.
const skills = [];
const previous = {};
function make(subject,key,band,topic,concept,meaning,why,rule,intuition,example,error,compare,validate,apply,extend,formula="",checks=[],prerequisites) {
  const sourceIds = subject === "calculus"
    ? [band >= 7 ? "quant-calculus-multiple" : "quant-calculus-single"]
    : [band <= 2 ? "quant-probability-rules" : "quant-distributions"];
  const record = {key,band,subject,topic,concept,meaning,why,rule,intuition,example,error,compare,validate,apply,extend,formula,checks,
    prerequisites: prerequisites ?? (previous[subject] ? [previous[subject]] : []),sourceIds};
  previous[subject] = key;
  skills.push(record);
}
const P = (...args) => make("probability",...args);
const C = (...args) => make("calculus",...args);
const check = (expression,value) => ({expression,value});

// Band 1: familiar quantities and pictures before notation.
P("prob-chance",1,"Probability basics","Probability as a chance",
  "A probability describes how likely an event is, from 0% to 100%.",
  "It lets you compare uncertain choices without calling any outcome certain.",
  "Convert a decimal probability to a percentage by multiplying by 100.",
  "Imagine 100 similar opportunities: a 20% chance means about 20 successes on average.",
  ["What percentage is a probability of 0.25?","0.25 × 100 = 25%."],
  ["Someone assigns a 130% chance of rain. What is wrong?","A probability cannot exceed 100%; the estimate is invalid."],
  ["How do 0.2 and 0.8 compare as chances?","20% versus 80%; the second is four times as likely."],
  ["Does a 30% forecast promise exactly 3 wins in the next 10 tries?","No. A short run can vary; 3 is the expected count, not a promise."],
  ["A supplier estimates a 5% delay chance. How many delays per 100 similar deliveries on average?","100 × 0.05 = 5 delays, if the estimate applies."],
  ["A 60% chance wins three trials in a row. Must the next trial lose?","No. Previous outcomes do not force a result; dependence must be assessed separately."],
  "percentage = 100 × probability",[check("0.25*100",25)]);
P("prob-complement",1,"Probability basics","The opposite event",
  "The complement of an event is everything where that event does not happen.",
  "It is often easier to count failures and subtract than list every success.",
  "P(not A) = 1 − P(A); A and not A cover all possibilities.",
  "One cake is the whole chance; success and failure are the two slices.",
  ["If a payment succeeds with 92% probability, what is its failure probability?","100% − 92% = 8%."],
  ["A 40% win chance is paired with a 40% loss chance, with no draws. What is missing?","The two must sum to 100%; loss is 60%."],
  ["Is 'not win' always the same as 'lose'?","Only when draws and other outcomes are impossible."],
  ["Before subtracting a chance from 100%, what must you identify?","The exact opposite event, including draws or cancelled outcomes if possible."],
  ["An app has a 3% crash chance per session. What is the no-crash chance?","100% − 3% = 97%."],
  ["Win, draw and lose chances are 50%, 20%, 30%. What is the chance of not winning?","Draw plus lose: 20% + 30% = 50%."],
  "P(Aᶜ) = 1 − P(A)",[check("1-.92",.08)]);
P("prob-equal-outcomes",1,"Probability basics","Equally likely outcomes",
  "When outcomes have equal chances, probability is the favorable count divided by all outcomes.",
  "This gives exact chances in simple fair games.",
  "P(event) = favorable outcomes / total equally likely outcomes.",
  "A fair spinner with four equal slices gives each slice 25%.",
  ["A fair six-sided die has two faces above 4. What is the chance of rolling above 4?","2/6 = 1/3, about 33.33%."],
  ["Three possible business outcomes are called equally likely merely because there are three. Why is that wrong?","Counting outcomes does not prove equal chances."],
  ["A fair coin versus a loaded coin: can you use 1/2 for heads in both?","Only for the fair coin; the loaded coin needs its actual probabilities."],
  ["What assumption permits favorable count divided by total count?","Every listed elementary outcome must be equally likely."],
  ["Four of 20 equally likely raffle tickets belong to you. Your winning chance?","4/20 = 20%."],
  ["Two independent fair coins are tossed. Is 'two heads, one head, zero heads' three equal outcomes?","No. HH, HT, TH, TT are equal; one head has 2/4 = 50%, the others 25% each."],
  "P(A) = |A| / |S| when elementary outcomes are equally likely",[check("2/6",1/3)]);
P("prob-base-rate",1,"Probability basics","Base rate",
  "A base rate is how often an event occurs in the relevant population before extra clues.",
  "It stops a striking signal from hiding how rare its target is.",
  "Start with the event count divided by the relevant population count.",
  "A rare item stays rare in a large pile unless a clue is strong enough to change that.",
  ["Ten of 1,000 products are defective. What is the defect base rate?","10/1,000 = 1%."],
  ["An alert sounds convincing, so the analyst ignores a 1% fraud rate. What is missing?","The low starting chance and the alert's false alarms."],
  ["A 1% defect base rate versus 10%: what changed?","The second population has ten times the starting defect chance."],
  ["Can last year's base rate automatically describe a new customer group?","No. Check whether the population and conditions are comparable."],
  ["Twenty of 400 applicants meet a qualification. What is the base rate?","20/400 = 5%."],
  ["Why can the same screening rule have different reliability in two populations?","Different base rates change the mix of true and false positive results."],
  "base rate = event count / population count",[check("10/1000",.01)]);
P("prob-conditional-group",1,"Probability basics","Conditional probability in counts",
  "A conditional probability measures a chance inside a specified group.",
  "It describes a customer segment or outcome after a clue is known.",
  "Restrict the denominator to people satisfying the condition.",
  "First enter one room; then count the successful people in that room.",
  ["Of 100 mobile visitors, 20 buy. What is the purchase chance among mobile visitors?","20/100 = 20%."],
  ["Twenty mobile buyers are divided by all 500 visitors to estimate mobile conversion. What is wrong?","Use the 100 mobile visitors as the denominator; 4% is the joint share of all visitors."],
  ["Is P(buy | mobile) the same as P(mobile | buy)?","No. They condition on different groups."],
  ["What must be nonzero when calculating a conditional probability?","The size or probability of the conditioning group."],
  ["Thirty of 60 approved applications renew. What is renewal probability given approval?","30/60 = 50%."],
  ["There are 40 buyers, including 20 mobile buyers, and 100 mobile visitors. Compare the reversed conditions.","P(buy | mobile) = 20%; P(mobile | buy) = 20/40 = 50%."],
  "P(A | B) = count(A and B) / count(B)",[check("20/100",.2)]);
P("prob-independence",1,"Probability basics","Independent events",
  "Events are independent when knowing one happened does not change the other's probability.",
  "Independence determines whether multiplying separate chances is valid.",
  "For independent A and B, P(A and B) = P(A) × P(B).",
  "Two separate fair coin tosses do not remember each other.",
  ["Two independent 50% wins are needed. What is the chance of both?","0.5 × 0.5 = 0.25 = 25%."],
  ["Two stocks have different names, so their losses are independent. What is wrong?","Different names do not remove shared market risks."],
  ["Can two independent events both happen?","Yes. Independence differs from events being mutually exclusive."],
  ["What should be checked before multiplying unconditional win probabilities?","Whether learning one result would change the other chance."],
  ["Independent backups fail with 10% and 20% chances. Probability both fail?","0.10 × 0.20 = 2%."],
  ["Five fair independent tosses were heads. What is the next head chance?","Still 50%; a losing or winning streak does not make the next toss due."],
  "P(A ∩ B) = P(A)P(B) for independent events",[check(".1*.2",.02)]);
P("prob-dependence",1,"Probability basics","Dependent events",
  "Events are dependent when one outcome changes the probability of another.",
  "Shared causes and removal of items can change combined risk.",
  "P(A and B) = P(A) × P(B | A).",
  "After taking one red ball from a small bag, fewer red balls remain.",
  ["A bag has 2 red and 2 blue balls. Draw without replacement. Probability both are red?","(2/4) × (1/3) = 1/6, about 16.67%."],
  ["Two draws without replacement use (2/4)². What is wrong?","The second red probability after a red draw is 1/3, not 1/2."],
  ["With replacement, what is the chance of two reds from the same bag?","(2/4)² = 25%, rather than about 16.67% without replacement."],
  ["What second-step chance belongs in a dependent sequence?","The chance conditional on the first step's actual outcome."],
  ["A supplier fails 10% of the time; a partner fails 50% given that failure. Chance both fail?","0.10 × 0.50 = 5%."],
  ["Two systems fail during the same power outage. Is the independence shortcut credible?","Usually not; the shared outage creates dependence and can raise joint failure risk."],
  "P(A ∩ B) = P(A)P(B | A)",[check("2/4*1/3",1/6)]);
P("prob-odds",1,"Probability basics","Probability versus odds",
  "Probability compares successes with all outcomes; odds compare successes with failures.",
  "It prevents confusing a chance with a success-to-failure ratio.",
  "Odds for success = p/(1−p); p = odds/(1+odds).",
  "One success and three failures means a 25% chance but odds of 1 to 3.",
  ["What probability corresponds to odds of 3 to 1 in favor?","3/(3+1) = 75%."],
  ["Odds of 1 to 4 are called a 25% chance. What is wrong?","The probability is 1/(1+4) = 20%."],
  ["What are the success odds when probability is 50%?","0.5/0.5 = 1, meaning 1 to 1."],
  ["What must '3 to 1' specify before interpretation?","Whether the odds are in favor or against the event."],
  ["A fair decimal payout of 4.0 returns four times the stake including stake. What chance breaks even?","1/4 = 25%, before fees."],
  ["Why is a bookmaker's quoted implied probability not necessarily the true chance?","Quotes include margin and market judgments; the underlying chance is uncertain."],
  "odds = p/(1−p); fair decimal payout = 1/p",[check("3/(3+1)",.75)]);
C("calc-function",1,"Functions and change","Function as a rule",
  "A function assigns one output to each allowed input.",
  "It turns a pricing or cost rule into predictions you can check.",
  "For y = f(x), choose x and apply the stated rule to obtain y.",
  "A machine takes a quantity in and returns a calculated cost.",
  ["A taxi model is C(x) = 5 + 2x euros for x kilometers. What is C(3)?","5 + 2 × 3 = €11."],
  ["The same input produces €10 and €15 under one supposedly complete rule. What is missing?","Another input or condition; a function has one output per complete input."],
  ["In C(x) = 5 + 2x, which number is fixed and which changes?","€5 is the fixed charge; €2x depends on distance."],
  ["What must you know before putting a number into a function?","Its input meaning, units, allowed range, and whether the model applies."],
  ["Revenue is R(q) = 10q euros. What is revenue from 8 units?","10 × 8 = €80."],
  ["Can a linear taxi model prove the real fare for any distance?","No. It is a model; surcharges and pricing limits may require extra terms."],
  "y = f(x)",[check("5+2*3",11)]);
C("calc-graph",1,"Functions and change","Reading a graph",
  "A graph places inputs on one axis and their outputs on another.",
  "It reveals increasing, decreasing and flat behavior quickly.",
  "Read the horizontal input first, then the corresponding vertical output.",
  "Trace upward from a chosen input until you reach the curve.",
  ["A revenue graph contains (3, 30). If x is units and y is euros, what does this point mean?","Selling 3 units produces €30 revenue."],
  ["A line looks steep, so its percent growth must be high. What is wrong?","Axis scales and starting values matter; visual steepness alone does not give percent growth."],
  ["A curve rises from €20 to €30. What is the absolute and relative increase?","€10; 10/20 = 50%."],
  ["What graph details must be checked before comparing slopes?","Units, scale, axis limits and whether either axis is logarithmic."],
  ["At price €5 demand is 100; at €6 it is 80. Which direction does the demand graph move?","Downward as price increases."],
  ["A chart omits the zero baseline. Does that invalidate every pattern?","No, but it can magnify apparent size; inspect actual values before judging the change."],
  "",[check("(30-20)/20",.5)]);
C("calc-slope",1,"Functions and change","Slope as change per unit",
  "Slope measures output change divided by input change.",
  "It tells you the extra cost or revenue per extra unit.",
  "Slope = (new output − old output)/(new input − old input).",
  "A ramp rises 2 meters over 10 horizontal meters: slope 0.2.",
  ["Cost grows from €30 at 5 units to €50 at 10 units. What is the average slope?","(50−30)/(10−5) = €4 per unit."],
  ["A €20 cost increase is called a slope of 20 without stating the quantity change. What is wrong?","Slope needs a denominator and units, not only the output difference."],
  ["A flat cost line versus an upward cost line: how do their slopes differ?","Flat has slope 0; upward has positive slope."],
  ["Why must two input values differ when calculating a slope?","A zero input difference would require division by zero."],
  ["A balance falls €60 while time increases 3 days. What is its average rate?","−60/3 = −€20 per day."],
  ["Can a two-point slope describe every point on a curved graph exactly?","No. It is an average over that interval; local rates may vary."],
  "m = Δy/Δx",[check("(50-30)/(10-5)",4)]);
C("calc-rate-units",1,"Functions and change","Rate units",
  "A rate's units are output units divided by input units.",
  "Correct units expose mistakes in speed, productivity and cost comparisons.",
  "Keep units with both the numerator and denominator.",
  "Meters per second tells you distance gained for each second.",
  ["A worker completes 24 tasks in 6 hours. What is the average task rate?","24/6 = 4 tasks per hour."],
  ["A cost rate of €2 per user is added directly to 100 users. What is wrong?","The units differ; multiply €2/user by 100 users to obtain €200."],
  ["How do 2 meters/second and 120 meters/minute compare?","They are equal because 2 × 60 = 120."],
  ["What must be aligned before comparing two measured rates?","The same units and compatible time intervals."],
  ["Support costs rise €90 for 30 extra tickets. What is the average added cost per ticket?","90/30 = €3 per ticket."],
  ["Traffic averages 10 visits/minute. Are 100 visits guaranteed in the next 10 minutes?","No. 100 is an average prediction; arrivals can vary."],
  "rate = output change/input change",[check("24/6",4)]);
C("calc-linear-model",1,"Functions and change","Linear model",
  "A linear rule has a constant slope and a fixed starting value.",
  "It gives a useful first approximation for cost, revenue and small changes.",
  "y = a + bx; a is the intercept and b the slope.",
  "A €10 entrance fee plus €3 per ride makes a straight cost line.",
  ["For C(q) = 10 + 3q euros, what is the cost of 4 rides?","10 + 3 × 4 = €22."],
  ["Doubling q must double a + bq. What is wrong?","The fixed charge a does not double; only the variable part does."],
  ["For C(q) = 10 + 3q, compare C(0) and the cost of one more ride.","C(0) = €10; every added ride costs €3."],
  ["When might a linear cost model stop being reasonable?","When bulk discounts, capacity limits or other changing marginal costs appear."],
  ["A service charges €20 monthly plus €0.50 per call. Cost for 100 calls?","20 + 0.50 × 100 = €70."],
  ["Sales rise 2 per euro of discount locally. Should the line be extended to unlimited discounts?","No. Local fit does not justify unlimited extrapolation or negative prices."],
  "y = a + bx",[check("10+3*4",22)]);

// Band 2: events, evidence, and local change.
P("prob-union",2,"Combining events","Inclusive OR",
  "A union includes outcomes where A, B, or both happen.",
  "It measures the chance of at least one relevant event.",
  "Count every included outcome once, even when it belongs to both events.",
  "Two overlapping circles form one combined region, without counting the overlap twice.",
  ["Of 100 users, 30 use search, 20 use bookmarks, and 10 use both. How many use either?","30 + 20 − 10 = 40 users, or 40%."],
  ["'A or B' is interpreted as excluding outcomes where both happen. What is wrong?","Probability's usual OR is inclusive; exactly one is a separate event."],
  ["How does 'at least one' differ from 'exactly one'?","At least one includes both; exactly one excludes both."],
  ["What extra count is needed when adding overlapping event counts?","The number in their overlap."],
  ["Two mutually exclusive defect types affect 4% and 6%. Probability of either defect?","4% + 6% = 10% because no product has both."],
  ["For independent 20% and 30% outages, what is the chance of at least one?","20% + 30% − (0.2 × 0.3 × 100%) = 44%."],
  "P(A ∪ B) = P(A) + P(B) − P(A ∩ B)",[check(".2+.3-.2*.3",.44)]);
P("prob-intersection",2,"Combining events","AND event",
  "An intersection includes only outcomes where both events happen.",
  "It distinguishes a combined requirement from either condition alone.",
  "P(A and B) = P(A)P(B | A), whether independent or not.",
  "Only the overlap of two circles passes both filters.",
  ["Half of users subscribe, and 40% of subscribers renew. What share does both?","0.5 × 0.4 = 20% of all users."],
  ["A 50% subscription chance and 40% conditional renewal chance are added. What is wrong?","Both conditions require multiplication: 20%, not 90%."],
  ["Can P(A and B) exceed P(A)?","No. The intersection is a subset of A."],
  ["What distinguishes a joint probability from a conditional probability?","Joint uses the full population; conditional uses the restricted group."],
  ["Twelve of 200 visitors are both mobile and buyers. What is the joint share?","12/200 = 6%."],
  ["P(A) = 80%, P(B) = 70%. Can both have chance 20%?","No. Their overlap is at least 80% + 70% − 100% = 50%."],
  "P(A ∩ B) = P(A)P(B | A)",[check(".5*.4",.2)]);
P("prob-disjoint",2,"Combining events","Mutually exclusive events",
  "Mutually exclusive events cannot happen together on the same trial.",
  "They simplify adding alternative outcomes.",
  "For disjoint A and B, P(A and B) = 0 and P(A or B) = P(A)+P(B).",
  "One die roll cannot be both 1 and 6.",
  ["A match has 40% home-win and 35% away-win chances. Chance either team wins?","40% + 35% = 75%; the remaining 25% is a draw."],
  ["Two nonzero disjoint events are called independent. What is wrong?","If one happens, the other's chance becomes 0; they are dependent."],
  ["Disjoint versus independent: which says 'cannot happen together'?","Disjoint. Independent says knowing one does not change the other's chance."],
  ["Before simply adding alternative chances, what must be checked?","The outcomes must not overlap."],
  ["A single order has 10% cancellation and 5% return chances, defined as exclusive outcomes. Chance either?","10% + 5% = 15%."],
  ["If A and B are disjoint with chances 30% and 20%, what is P(B | A)?","0%, provided A occurred; B cannot occur with A."],
  "A ∩ B = ∅; P(A ∪ B) = P(A)+P(B)",[check(".4+.35",.75)]);
P("prob-total",2,"Conditional probability","Total probability",
  "An overall chance is a weighted average of chances across exhaustive, nonoverlapping groups.",
  "It combines segment risks without giving every segment equal weight.",
  "P(A) = Σ P(group) × P(A | group).",
  "Mix a large low-risk bucket with a small high-risk bucket using their actual sizes.",
  ["80% of orders have 1% defects; 20% have 6%. Overall defect chance?","0.8 × 0.01 + 0.2 × 0.06 = 2%."],
  ["The two defect rates 1% and 6% are averaged as 3.5%. What is wrong?","The groups are unequal; their 80%/20% weights matter."],
  ["What happens if every group's event rate is 5%?","The overall rate is 5%, regardless of group weights."],
  ["What must the grouping satisfy for total probability?","Groups must cover all outcomes once and their weights sum to 100%."],
  ["60% of customers use mobile with 10% conversion; 40% use desktop with 20%. Overall conversion?","0.6 × 0.1 + 0.4 × 0.2 = 14%."],
  ["Can overall conversion rise when each segment's rate stays fixed?","Yes. More traffic can move to the higher-converting segment."],
  "P(A) = Σᵢ P(Bᵢ)P(A | Bᵢ)",[check(".8*.01+.2*.06",.02)]);
P("prob-bayes-counts",2,"Conditional probability","Bayes with natural counts",
  "Bayes updates a starting chance after evidence by comparing all ways that evidence arises.",
  "It reveals how false alarms can dominate a rare-event test.",
  "Among positive results, divide true positives by all positives.",
  "Put genuine alarms and false alarms in one tray; ask what share are genuine.",
  ["In 1,000 people, 10 have a condition. A test gives 9 true and 99 false positives. Chance of the condition among positives?","9/(9+99) = 9/108 ≈ 8.33%."],
  ["The test detects 90% of cases, so a positive means a 90% disease chance. What is wrong?","Detection among cases differs from disease among positives; the base rate and false positives matter."],
  ["If false positives fall from 99 to 9 while true positives stay 9, what is the positive predictive value?","9/(9+9) = 50%, rather than about 8.33%."],
  ["What counts are needed to interpret a positive result?","True positives and false positives in the relevant population."],
  ["A fraud filter finds 20 frauds and flags 80 legitimate orders. What share of flagged orders are fraudulent?","20/(20+80) = 20%."],
  ["Can a positive result still increase risk even when most positives are false?","Yes. The example rises from a 1% base rate to about 8.33%, but remains below 50%."],
  "P(A | positive) = true positives/(true positives+false positives)",[check("9/108",1/12)]);
P("prob-tree",2,"Conditional probability","Probability tree",
  "A probability tree separates sequential choices into branches.",
  "It keeps conditional chances and alternative routes organized.",
  "Multiply along a route; add across mutually exclusive routes.",
  "Branches are roads; reaching one destination may involve several separate roads.",
  ["A fair coin is tossed twice independently. Chance of exactly one head?","HT and TH each have 25%; 25% + 25% = 50%."],
  ["The chances on two successive branches are added. What is wrong?","Multiply along a route; addition is for separate alternative routes."],
  ["How do 'both stages succeed' and 'either stage succeeds' use a tree differently?","Both follows one success-success route; either combines all routes containing a success."],
  ["What must all branches leaving the same node sum to?","100%, including all possibilities conditional on reaching that node."],
  ["Half of users get A, half B. Conversion is 10% on A and 20% on B. Overall conversion?","0.5 × 0.1 + 0.5 × 0.2 = 15%."],
  ["A second-stage rate was measured only among first-stage successes. Can you apply it to failures too?","No. That is a different branch and needs its own conditional probability."],
  "route probability = product of branch probabilities",[check(".5*.1+.5*.2",.15)]);
P("prob-replacement",2,"Sampling and chance","Sampling with replacement",
  "Replacement restores the item before another random draw.",
  "It determines whether the population composition changes between draws.",
  "Under independent reshuffled replacement, each draw uses the original probabilities.",
  "Returning a ball resets the bag; keeping it changes the next draw.",
  ["A bag has 1 red among 5 balls. Two independent draws replace the ball. Chance both red?","(1/5)² = 4%."],
  ["Without replacement, the only red ball is drawn, but the next red chance is kept at 20%. What is wrong?","No red remains; the next red chance is 0%."],
  ["From 1 red and 4 blue, how do two-red chances compare with and without replacement?","With replacement 4%; without replacement 0%."],
  ["Besides returning an item, what supports independent repeated draws?","Proper random mixing and a stable draw mechanism."],
  ["A deck has 4 aces in 52 cards. After an ace is removed, next-card ace chance?","3/51 ≈ 5.88%, instead of 4/52 ≈ 7.69%."],
  ["Why can sampling a few people from a huge population be approximately independent without replacement?","Removing a few people barely changes the remaining proportions; the approximation needs a small sampling fraction."],
  "with replacement: P(two successes) = p² when draws are independent",[check("(1/5)**2",.04)]);
C("calc-average-change",2,"Rates of change","Average rate of change",
  "An average rate spreads a total change over a whole input interval.",
  "It summarizes growth over a period without claiming constant speed.",
  "Average rate = [f(b)−f(a)]/(b−a).",
  "A trip average hides fast and slow stretches.",
  ["Users grow from 100 to 160 over 3 days. Average growth rate?","(160−100)/3 = 20 users/day."],
  ["Average growth is 20/day, so each day added exactly 20. What is wrong?","The average does not determine the path between the endpoints."],
  ["Is adding 20 users/day the same as growing 20%/day?","No. A count rate is absolute; a percentage rate depends on the starting size."],
  ["What endpoint information is required for an average rate?","Both input values and both output values, using consistent units."],
  ["Revenue drops from €500 to €380 over 4 weeks. Average weekly change?","(380−500)/4 = −€30/week."],
  ["Two apps have equal average growth but one lost users then recovered. Are their histories identical?","No. Endpoint averages can hide volatility and timing."],
  "average rate = [f(b)−f(a)]/(b−a)",[check("(160-100)/3",20)]);
C("calc-curved-function",2,"Rates of change","Changing slopes",
  "A curved relationship can have different slopes at different inputs.",
  "It warns against treating every extra sale or user as equally costly.",
  "Calculate separate interval slopes and compare them.",
  "A hill can get steeper as you climb; one slope does not describe the whole hill.",
  ["For f(x)=x², compare the average slopes from 1 to 2 and from 2 to 3.","(4−1)/1 = 3; (9−4)/1 = 5. The second slope is larger."],
  ["Because f(2)=4, the slope at 2 must be 4. What is wrong?","Function value and slope are different quantities; local slope requires change around 2."],
  ["For f(x)=3x, do interval slopes change with x?","No. Every interval slope is 3 because the function is linear."],
  ["What evidence can suggest a constant-slope assumption is poor?","Measured interval slopes change systematically with input size."],
  ["C(q)=q² euros. Cost rises from q=10 to q=11. Added cost?","11²−10² = €21."],
  ["Why might a business's next 1,000 users cost more than its first 1,000?","Capacity pressure can make marginal cost rise; test the cost curve rather than assume linearity."],
  "interval slope = [f(x+h)−f(x)]/h",[check("(9-4)/(3-2)",5)]);
C("calc-limit-intuition",2,"Limits and local change","Limit",
  "A limit describes the value a function approaches as its input approaches a point.",
  "It provides the precise basis for an instantaneous rate.",
  "Inspect values closer to the point from both sides; both approaches must agree for a two-sided limit.",
  "You can approach a doorway without yet standing in it.",
  ["As x approaches 3, what does 2x+1 approach?","2 × 3 + 1 = 7."],
  ["A function is undefined at x=2, so it cannot have a limit there. What is wrong?","Nearby values can approach one value even when the point itself is missing."],
  ["Does a function's value at a point always equal its limit there?","Only if it is continuous at that point."],
  ["Why examine both sides when finding a two-sided limit?","Different left and right approaches mean the two-sided limit does not exist."],
  ["For x≠2, (x²−4)/(x−2)=x+2. Its limit as x approaches 2?","4, although the original expression is undefined at 2."],
  ["A fee jumps from €0 below 100 units to €10 at 100. Can the two-sided fee limit at 100 exist?","Not when the left approach is €0 and the right approach is €10."],
  "limₓ→a f(x) = value approached near a",[check("2*3+1",7)]);
C("calc-local-rate",2,"Limits and local change","Instantaneous rate",
  "An instantaneous rate is the limiting average rate over a shrinking interval.",
  "It describes how fast a quantity changes at one input value.",
  "Use nearby changes and shrink the interval, when the limit exists.",
  "A speedometer shows local speed; the trip average summarizes the whole journey.",
  ["For distance s(t)=t² meters, the average speed from t=2 to t=2.1 is what?","(2.1²−2²)/0.1 = 4.1 meters/second."],
  ["A one-hour average speed is called the exact speed at the end. What is wrong?","A long-interval average need not equal the endpoint's local rate."],
  ["For s(t)=t², shrinking the interval around t=2 gives what speed?","4 meters/second, approached by the nearby average speeds."],
  ["When can an instantaneous rate fail to exist?","At a sharp corner, jump, or another point without a finite common slope limit."],
  ["A curve changes by approximately €6 for a 0.2-unit increase near q=5. Approximate local rate?","6/0.2 = €30 per unit near q=5."],
  ["Is a local rate enough to forecast a very large change?","Usually not. The slope can change; a small-change approximation should stay local."],
  "f′(a) = limₕ→0 [f(a+h)−f(a)]/h",[check("(2.1**2-2**2)/.1",4.1)]);
C("calc-continuity",2,"Limits and local change","Continuity",
  "A function is continuous at a point when its nearby limit equals its value there.",
  "It tells you whether small input changes can avoid a jump in output.",
  "Check that the value exists, the limit exists, and they are equal.",
  "A connected road has no missing piece or sudden teleport at that point.",
  ["Is f(x)=2x+1 continuous at x=3?","Yes. f(3)=7 and nearby values approach 7."],
  ["Every continuous function must have a smooth slope. What is wrong?","A continuous curve can have a corner; continuity does not guarantee differentiability."],
  ["Is |x| continuous at 0, and is its derivative there defined?","It is continuous; its left slope is −1 and right slope is +1, so no derivative exists there."],
  ["What three checks establish continuity at a?","f(a) exists, the limit as x→a exists, and the two are equal."],
  ["A delivery fee changes abruptly at an order threshold. Is the fee continuous at that threshold?","No, if the left and right values differ."],
  ["Why can a tiny price change have a large demand effect despite a smooth model?","Real behavior can have thresholds or discrete choices; check whether continuity is a suitable approximation."],
  "continuity at a: limₓ→a f(x)=f(a)",[check("Math.abs(0)",0)]);

// Band 3: random quantities and derivative rules.
P("prob-random-variable",3,"Random variables","Random variable",
  "A random variable assigns a number to each possible random outcome.",
  "It turns uncertain results into quantities such as profit or delay.",
  "Define the numerical outcome and its units before assigning probabilities.",
  "A coin outcome becomes +€2 for heads or −€1 for tails.",
  ["A fair coin pays +€2 on heads and −€1 on tails. What values can profit X take?","X can be +€2 or −€1, each with probability 50%."],
  ["A random variable is said to be only its average. What is wrong?","The variable has possible outcomes; its average summarizes them."],
  ["Is the event 'profit is positive' the same as profit X?","No. X is a numerical quantity; X>0 is an event."],
  ["Before comparing two profit distributions, what must match?","The time horizon, units, stake definition and treatment of fees."],
  ["Delivery delay is 0, 1 or 2 days. Is delay a random variable?","Yes. It assigns a numerical number of days to each delivery."],
  ["Why should a trading model define net rather than gross profit?","Fees and slippage change the numerical outcomes and therefore expected profitability."],
  "",[check(".5*2+.5*(-1)",.5)]);
P("prob-mass-function",3,"Random variables","Probability mass function",
  "A probability mass function gives a probability to each possible discrete value.",
  "It describes a whole count or payout distribution rather than one average.",
  "Each probability is nonnegative and all possible values' probabilities sum to 1.",
  "Allocate the whole 100% chance across labeled boxes.",
  ["X=0,1,2 has probabilities 20%,50%,30%. What is P(X=2)?","30%."],
  ["Probabilities 40%,40%,30% are presented as a complete mass function. What is wrong?","They total 110%; a complete distribution must total 100%."],
  ["Does the most likely value have to carry more than 50% probability?","No. The largest probability can still be below 50%."],
  ["What checks make a proposed discrete probability table valid?","No negative probabilities, every possible value covered, and total probability 100%."],
  ["For the 20%/50%/30% distribution, what is P(X≥1)?","50% + 30% = 80%."],
  ["A payout table leaves out cancellations. Why can expected profit be wrong?","It omits an outcome; its probability and payout must be included."],
  "p(x)=P(X=x); Σₓp(x)=1",[check(".2+.5+.3",1)]);
P("prob-cumulative",3,"Random variables","Cumulative distribution",
  "A cumulative distribution F(x) gives the probability that X is at most x.",
  "It answers questions about thresholds, delivery limits and loss cutoffs.",
  "F(x)=P(X≤x); accumulate all probability up to x.",
  "Fill a bucket from the smallest outcomes upward.",
  ["X=0,1,2 has probabilities 20%,50%,30%. What is F(1)?","P(X≤1)=20%+50%=70%."],
  ["A cumulative probability falls as the threshold rises. What is wrong?","Adding possible outcomes cannot reduce cumulative probability."],
  ["For the same table, how do P(X<1) and P(X≤1) differ?","20% versus 70%; the second includes the mass at X=1."],
  ["What must a cumulative distribution do as its threshold increases?","Never decrease; it stays between 0 and 1."],
  ["A delivery CDF gives F(3 days)=0.9. What share arrives later?","1−0.9=10%, using the same delivery population."],
  ["F(5)=80% and F(2)=30%. What is P(2<X≤5)?","80%−30%=50%."],
  "F(x)=P(X≤x)",[check(".2+.5",.7)]);
P("prob-continuous",3,"Random variables","Discrete versus continuous",
  "Discrete variables use separate possible values; continuous models spread probability over intervals.",
  "It determines whether to sum individual masses or integrate a density.",
  "Count values for discrete models; use intervals for continuous probabilities.",
  "Number of customers is countable; arrival time can be modeled on a continuous clock.",
  ["Is number of orders discrete or continuous?","Discrete: 0,1,2,... orders."],
  ["A continuous waiting-time model assigns 20% probability to exactly 3.000... seconds. What is wrong?","An individual point has probability 0 under a continuous density; a time interval can have positive probability."],
  ["Is a price recorded to cents perfectly continuous?","Recorded cents are discrete; a continuous model may still be a useful approximation."],
  ["What must be checked when using a continuous approximation to counts?","Whether rounding and small counts materially change the probabilities."],
  ["Uniform waiting time from 0 to 10 minutes: probability between 2 and 4 minutes?","Interval length 2/10 = 20%."],
  ["Why is a 0% exact-point probability compatible with eventually observing a time?","One of infinitely many points occurs; probability is assigned to ranges, not a positive mass at each exact point."],
  "",[check("(4-2)/10",.2)]);
P("prob-density",3,"Random variables","Probability density",
  "A density's area over an interval is the probability of that interval.",
  "It prevents mistaking a curve's height for a percentage chance.",
  "Density is nonnegative, and its total area is 1.",
  "Height is like water depth; probability is depth times width, or area under a varying curve.",
  ["Uniform X on [0,0.5] has density 2. Probability X lies in [0,0.1]?","2 × 0.1 = 0.2 = 20%."],
  ["A density height of 2 is rejected because probabilities cannot exceed 1. What is wrong?","Density is not probability; its area, rather than height, is bounded by 1."],
  ["If a uniform interval doubles in width, what happens to its density height?","It halves so total area stays 1."],
  ["How do you check a proposed density?","Its height must be nonnegative and total area must equal 1."],
  ["A constant density of 0.25 covers [0,4]. Total probability?","0.25 × 4 = 1 = 100%."],
  ["Why do density units change when seconds are converted to minutes?","Density is probability per input unit; area remains the same after the unit conversion."],
  "P(a≤X≤b)=∫ₐᵇ f(x)dx; ∫f(x)dx=1",[check("2*.1",.2)]);
P("prob-rv-mean",3,"Random variables","Expected value of a random variable",
  "Expected value is the probability-weighted average of a random quantity.",
  "It summarizes average profit, waiting time or demand across repeated comparable cases.",
  "Multiply each value by its probability, then sum.",
  "Each outcome gets a vote proportional to its chance.",
  ["Profit is €10 with chance 20% and €0 otherwise. Expected profit?","0.2 × 10 + 0.8 × 0 = €2."],
  ["Expected payout is €2, so every play must pay €2. What is wrong?","€2 is an average; an individual play pays €10 or €0."],
  ["Can expected value be a value the variable never actually takes?","Yes. Here €2 is never the actual payout."],
  ["What must be included when computing expected net profit?","All possible net outcomes, their probabilities, and costs such as stake and fees."],
  ["Delay is 0 days with 60% chance and 2 days with 40%. Expected delay?","0.6 × 0 + 0.4 × 2 = 0.8 days."],
  ["A €2 expected payout costs €3 to enter. Expected net result?","€2−€3=−€1 per play."],
  "E[X]=Σₓ xP(X=x)",[check(".2*10+.8*0",2)]);
P("prob-rv-variance",3,"Random variables","Variance of a random variable",
  "Variance is the probability-weighted squared distance from the mean.",
  "It separates average reward from how widely outcomes vary.",
  "Var(X)=E[(X−E[X])²]; standard deviation is its square root.",
  "Two routes can have the same average arrival time but different reliability.",
  ["X is 0 or 2 with equal chance. Its mean is 1. What is its variance?","0.5(0−1)²+0.5(2−1)²=1; SD=1."],
  ["Zero expected profit means zero risk. What is wrong?","Positive and negative outcomes can average to zero while varying greatly."],
  ["Compare certain €1 with equally likely €0 or €2.","Both mean €1; the certain value has variance 0, the uncertain payout variance 1 euro²."],
  ["What units does variance have when profit is measured in euros?","Euros squared; standard deviation returns to euros."],
  ["X is −€10 or +€10 with equal chance. Mean and SD?","Mean €0; variance 100 euro²; SD €10."],
  ["Does lower variance always mean a better choice?","No. Reward, downside shape, costs and personal constraints also matter."],
  "Var(X)=E[X²]−E[X]²",[check(".5*(0-1)**2+.5*(2-1)**2",1)]);
P("prob-bernoulli",3,"Discrete distributions","Bernoulli trial",
  "A Bernoulli variable records one success as 1 and failure as 0.",
  "It models one conversion, win, defect or yes/no outcome.",
  "P(X=1)=p; P(X=0)=1−p; E[X]=p; Var(X)=p(1−p).",
  "A yes/no light with an uncertain chance of switching on.",
  ["A visitor converts with probability 20%. What is the mean of the 0/1 conversion variable?","0.2; across visitors that represents a 20% conversion rate."],
  ["A match with win, draw and lose is automatically a Bernoulli outcome. What is wrong?","It has three outcomes unless you define success versus all other results."],
  ["At p=0 or p=1, what is the Bernoulli variance?","0; the outcome is certain under the model."],
  ["What definition must be fixed before recording Bernoulli successes?","Exactly what counts as success, with a consistent observation window."],
  ["At p=0.2, what is Var(X)?","0.2 × 0.8 = 0.16."],
  ["Does defining each result as 0 or 1 make repeated results independent?","No. Bernoulli outcomes can still be dependent."],
  "E[X]=p; Var(X)=p(1−p)",[check(".2*.8",.16)]);
C("calc-derivative",3,"Derivatives","Derivative notation",
  "The derivative f′(x) is a function giving the local rate of change of f at x.",
  "It answers how much an output changes for a tiny input change.",
  "f′(a)=lim as h→0 of [f(a+h)−f(a)]/h, when the limit exists.",
  "Zoom into a smooth curve until it resembles a straight line.",
  ["For f(x)=x², what is f′(3)?","f′(x)=2x, so f′(3)=6."],
  ["f′(3)=6 is described as f(3)=6. What is wrong?","The derivative is a slope; the function value is f(3)=9."],
  ["How do f′(x) and f′(3) differ?","The first gives a rate for any allowed x; the second evaluates it at x=3."],
  ["What must hold for the derivative definition at a point?","The difference-quotient limit must exist and be finite."],
  ["C′(10)=€4/unit. What does that suggest for a small 0.1-unit change?","Approximately €4 × 0.1 = €0.40 added cost."],
  ["Does a zero derivative at one point imply the entire function is constant?","No. It may be flat only at that point, such as x² at 0."],
  "f′(a)=limₕ→0 [f(a+h)−f(a)]/h",[check("2*3",6)]);
C("calc-power-rule",3,"Derivatives","Power rule",
  "The power rule differentiates x raised to a fixed power.",
  "It makes polynomial growth and cost slopes easy to calculate.",
  "For a fixed real exponent n, d(xⁿ)/dx = nxⁿ⁻¹ where the expression is defined and differentiable.",
  "A square's slope grows linearly; a cube's slope grows quadratically.",
  ["Differentiate f(x)=x³ and evaluate the derivative at x=2.","f′(x)=3x²; f′(2)=12."],
  ["The derivative of x³ is written x². What is missing?","The factor 3; the derivative is 3x²."],
  ["Compare derivatives of x and x².","They are 1 and 2x; only the latter changes with x."],
  ["What domain issue matters for fractional powers?","Real-valued roots and derivative formulas may require x>0 or other domain restrictions."],
  ["For f(x)=√x with x>0, what is f′(4)?","f′(x)=1/(2√x); at 4 it is 1/4=0.25."],
  ["For cost C(q)=2q² euros, what is marginal cost at q=5?","C′(q)=4q, so C′(5)=€20/unit."],
  "d(xⁿ)/dx=nxⁿ⁻¹",[check("3*2**2",12)]);
C("calc-sum-rule",3,"Derivatives","Constant and sum rules",
  "Differentiate sums term by term; a fixed constant has zero derivative.",
  "It separates fixed charges from changing cost components.",
  "d(a+bf(x))/dx = b f′(x), for constants a and b.",
  "A fixed entrance charge changes the bill level but not the cost of another ride.",
  ["Differentiate C(q)=50+3q+q².","C′(q)=3+2q; the €50 fixed charge contributes zero slope."],
  ["The derivative of 50 is written 50. What is wrong?","A constant does not change, so its derivative is 0."],
  ["What changes when €100 is added to a cost function?","The cost level increases by €100; marginal cost stays the same."],
  ["What must be constant when you treat a coefficient as fixed?","It must not itself depend on the differentiation variable."],
  ["For C(q)=50+3q+q², what is marginal cost at q=4?","3+2×4=€11/unit."],
  ["If the fee a depends on quantity q, may you drop its derivative?","No. Then a(q) is a changing term and contributes a′(q)."],
  "d(a+bf+cg)/dx=bf′+cg′",[check("3+2*4",11)]);
C("calc-tangent",3,"Derivatives","Local linear approximation",
  "A tangent line approximates a smooth function near one input.",
  "It estimates the effect of a small change without recomputing a full model.",
  "f(a+h) ≈ f(a)+f′(a)h for small h.",
  "A curved road looks straight over a short stretch.",
  ["For f(x)=x² near x=10, estimate f(10.1).","100 + 20 × 0.1 = 102; the exact value is 102.01."],
  ["A tangent approximation is applied far from its base point as an exact result. What is wrong?","It is local and approximate; curvature creates error."],
  ["For a linear function, is its tangent approximation exact?","Yes, throughout its valid domain, because the slope is constant."],
  ["What controls whether a tangent approximation is useful?","The size of the input change and how quickly the slope changes nearby."],
  ["Revenue is €500 and local slope €8/unit. Estimate revenue after 0.5 more units.","€500 + €8 × 0.5 ≈ €504."],
  ["For x² near 10, compare approximation error for h=0.1 and h=1.","Errors are h²: 0.01 and 1. A tenfold step makes this error 100 times larger."],
  "f(a+h)≈f(a)+f′(a)h",[check("100+20*.1",102)]);
C("calc-marginal-cost",3,"Economic derivatives","Marginal cost",
  "Marginal cost is the local rate of cost change with output quantity.",
  "It helps decide whether a small increase in production is worth its extra cost.",
  "Marginal cost = C′(q); it approximates extra cost for a small quantity increase.",
  "The next item can cost differently from the average of all past items.",
  ["C(q)=100+2q² euros. What is marginal cost at q=5?","C′(q)=4q, so €20/unit."],
  ["Total cost divided by units is called marginal cost. What is wrong?","That is average cost; marginal cost measures additional cost."],
  ["At q=5, compare average and marginal cost for C(q)=100+2q².","Total €150; average €30/unit; marginal €20/unit."],
  ["When does a derivative poorly estimate the cost of one whole extra unit?","When units are large or discrete and cost curves strongly bend or jump."],
  ["For the same cost rule, exact cost increase from 5 to 6 units?","C(6)−C(5)=172−150=€22, versus the €20 derivative estimate."],
  ["Marginal revenue is €25 and marginal cost €20. What does a small increase suggest?","About €5/unit extra profit locally, subject to capacity and model assumptions."],
  "MC(q)=C′(q)",[check("2*6**2-2*5**2",22)]);

// Band 4: standard distributions and differentiation techniques.
P("prob-binomial",4,"Discrete distributions","Binomial count",
  "A binomial variable counts successes in a fixed number of independent, identical-chance trials.",
  "It models conversions or wins when those assumptions are credible.",
  "For n trials with success chance p: E[X]=np and Var(X)=np(1−p).",
  "Place n independent yes/no lights side by side and count those lit.",
  ["Ten independent trials each have 20% success chance. Expected successes?","10 × 0.2 = 2."],
  ["A binomial model uses varying customer probabilities as if all were equal. What is wrong?","The standard model requires a common success probability; heterogeneity may need another model."],
  ["Does an expected count of 2 require observing exactly 2?","No. The actual count varies between 0 and 10."],
  ["What are the key binomial assumptions?","Fixed n, binary outcomes, independent trials and a constant probability p."],
  ["For n=10 and p=0.2, what is count variance?","10 × 0.2 × 0.8 = 1.6."],
  ["Why may repeat visits from one person violate a simple conversion binomial model?","Their outcomes can be correlated; ten visits are not necessarily ten independent people."],
  "P(X=k)=C(n,k)pᵏ(1−p)ⁿ⁻ᵏ",[check("10*.2*.8",1.6)]);
P("prob-binomial-tail",4,"Discrete distributions","Binomial tail",
  "A tail probability adds chances of counts at or beyond a chosen threshold.",
  "It measures whether an observed run or count is unusual under a stated model.",
  "For at least one success, use 1−P(no successes)=1−(1−p)ⁿ.",
  "Count all paths reaching the target, not just one exact result.",
  ["Three independent trials each succeed with 20% chance. Chance of at least one success?","1−0.8³=0.488=48.8%."],
  ["Three 20% chances are added to get an exact 60% at-least-one chance. What is wrong?","Success events overlap; use the complement or full binomial sum."],
  ["How do P(X≥2) and P(X=2) differ?","The first also includes 3,4,...; the second includes only exactly 2."],
  ["What must be stated when calling a count unusual?","The trial model, threshold direction and whether it was chosen before seeing data."],
  ["Two independent fair coin tosses: chance of at least one head?","1−0.5²=75%."],
  ["After searching 100 different runs, one unusual run is found. Is its single-run probability the full search probability?","No. The search adds opportunities for unusual outcomes and must be accounted for."],
  "P(X≥1)=1−(1−p)ⁿ",[check("1-.8**3",.488)]);
P("prob-geometric",4,"Discrete distributions","Geometric waiting count",
  "A geometric variable counts independent trials until the first success.",
  "It models waiting for a first conversion under a stable chance.",
  "Counting the successful trial, P(T=k)=(1−p)ᵏ⁻¹p and E[T]=1/p.",
  "Miss, miss, then hit; the waiting count includes that final hit.",
  ["Independent trials succeed with 25% chance. Expected trials to first success?","1/0.25=4 trials."],
  ["An expected wait of four means success is due on trial four. What is wrong?","It is an average, and each independent trial still has 25% success chance."],
  ["At p=25%, chance the first success occurs on trial 2?","0.75 × 0.25 = 18.75%."],
  ["Which counting convention must be specified for a geometric variable?","Trials until success versus failures before success; their values differ by one."],
  ["With p=20%, chance of no success in the first 3 trials?","0.8³=51.2%."],
  ["A sales team gets better after every call. Is a constant-p geometric model exact?","No. Learning changes p; the waiting process needs changing probabilities."],
  "P(T=k)=(1−p)ᵏ⁻¹p; E[T]=1/p",[check("1/.25",4)]);
P("prob-poisson",4,"Discrete distributions","Poisson event count",
  "A Poisson distribution models an event count with parameter λ, the expected count in the interval.",
  "It is useful for approximately independent arrivals at a stable rate.",
  "P(X=k)=e⁻λ λᵏ/k!; mean and variance both equal λ.",
  "Count independent drops landing in a fixed time bucket.",
  ["A Poisson model averages 2 requests/minute. Probability of zero in a minute?","e⁻²≈0.1353=13.53%."],
  ["Poisson means arrivals are evenly spaced. What is wrong?","Counts and waiting gaps fluctuate; a constant average rate does not mean fixed spacing."],
  ["How does λ change from one minute to three at a constant 2/minute rate?","From 2 to 6 expected arrivals."],
  ["What patterns make a simple Poisson model doubtful?","Strong clustering, dependence or a rate that changes during the interval."],
  ["Under Poisson λ=4, what are the mean and SD?","Mean 4 events; variance 4; SD √4=2 events."],
  ["Observed count variance is 20 while mean is 4. What deserves checking?","Overdispersion, varying rates or clustering; a simple Poisson model implies variance 4."],
  "P(X=k)=e⁻λ λᵏ/k!; E[X]=Var(X)=λ",[check("Math.exp(-2)",0.1353352832366127)]);
P("prob-exponential",4,"Continuous distributions","Exponential waiting time",
  "An exponential distribution models waiting time in a constant-rate Poisson process.",
  "It connects event rates with the chance of waiting beyond a threshold.",
  "With rate λ>0, P(T>t)=e⁻λt for t≥0; E[T]=1/λ.",
  "A steady random arrival stream still has both short and long gaps.",
  ["Arrivals have constant rate 2/minute. Expected exponential waiting time?","1/2 minute = 0.5 minute = 30 seconds."],
  ["A rate of 2/minute is used as a mean waiting time of 2 minutes. What is wrong?","Waiting mean is the inverse rate, 0.5 minute."],
  ["At rate 2/minute, chance of waiting more than 1 minute?","e⁻²≈13.53%."],
  ["What units must match in e⁻λt?","Rate and time must be reciprocal, so λt is dimensionless."],
  ["Rate is 0.5/hour. Expected waiting time?","1/0.5=2 hours."],
  ["Why is this waiting model weak for a task whose failure risk rises with age?","The exponential model has constant hazard; aging requires a different risk pattern."],
  "P(T>t)=e⁻λt; E[T]=1/λ",[check("1/2",.5)]);
P("prob-uniform",4,"Continuous distributions","Uniform distribution",
  "A continuous uniform distribution gives equal probability to equal-length intervals inside its range.",
  "It is a simple model when no position within a bounded interval is favored.",
  "For [a,b] with a<b, density=1/(b−a), mean=(a+b)/2.",
  "A flat probability shelf spreads area evenly over the allowed range.",
  ["X is uniform from 10 to 20 minutes. Chance X is between 12 and 15?","(15−12)/(20−10)=30%."],
  ["Unknown outcomes are called uniform merely because no data exist. What is wrong?","Lack of knowledge does not show all ranges are equally likely."],
  ["For uniform [10,20], what are mean and median?","Both are 15."],
  ["What must be justified when assuming a uniform model?","The bounds and equal density across the full interval."],
  ["Uniform price change from −€2 to +€2: probability of a positive change?","Half the interval: 50%."],
  ["Does equal probability per euro stay uniform after taking the logarithm?","Generally no. A nonlinear transformation changes density."],
  "f(x)=1/(b−a); E[X]=(a+b)/2",[check("(15-12)/(20-10)",.3)]);
P("prob-normal",4,"Continuous distributions","Normal distribution",
  "A normal distribution is a symmetric bell-shaped model determined by mean μ and SD σ.",
  "It provides a useful approximation for some measurement errors and averages.",
  "About 68% lies within 1 SD, 95% within 2 SD, and 99.7% within 3 SD.",
  "Most values gather near the center, with progressively fewer farther away.",
  ["A normal measurement has mean 100 and SD 10. Approximate share between 90 and 110?","About 68%, because the interval is one SD around the mean."],
  ["Every real-world dataset must follow a normal curve. What is wrong?","Normality is an assumption; skew, bounds, mixtures and heavy tails can invalidate it."],
  ["For a normal distribution, how do mean, median and mode compare?","All equal μ."],
  ["What must be checked before using normal tail probabilities for losses?","Whether the tail shape and dependence match the model, not just the center."],
  ["Normal mean 100, SD 10: approximate share above 120?","About 2.3%, using the standard normal upper tail at z=2."],
  ["Can a normal model be exact for a quantity that can never be negative?","Not if it assigns material negative probability; a positive-valued model may be better."],
  "z=(x−μ)/σ; f(x)=exp(−(x−μ)²/(2σ²))/(σ√(2π))",[check("(120-100)/10",2)]);
C("calc-product-rule",4,"Derivative techniques","Product rule",
  "When two changing quantities are multiplied, both contribute to the derivative.",
  "It differentiates revenue when price and quantity both vary.",
  "(fg)′=f′g+fg′.",
  "Rectangle area changes when either its width or its height changes.",
  ["Differentiate f(x)=x(x+2).","1×(x+2)+x×1 = 2x+2."],
  ["The derivative of fg is written f′g′. What is wrong?","Use f′g+fg′; multiplying derivatives loses the two contributions."],
  ["If g is constant, how does the product rule simplify?","g′=0, so (fg)′=gf′."],
  ["What should be checked before using the product rule?","Both functions must be differentiable at the point of interest."],
  ["Revenue R(p)=p(100−2p). What is R′(10)?","R′(p)=100−4p; at 10 it is 60 quantity units of revenue per price unit."],
  ["Does raising price necessarily raise revenue when demand falls?","No. The positive price contribution competes with the negative demand contribution."],
  "(fg)′=f′g+fg′",[check("100-4*10",60)]);
C("calc-quotient-rule",4,"Derivative techniques","Quotient rule",
  "The quotient rule differentiates one changing quantity divided by another.",
  "It finds rates of change of ratios such as average cost.",
  "(f/g)′=(f′g−fg′)/g², with g≠0.",
  "A ratio changes when its numerator rises or its denominator grows.",
  ["Average cost A(q)=100/q+2. What is A′(10)?","A′(q)=−100/q²; at 10 it is −1."],
  ["The derivative of f/g is written f′/g′. What is wrong?","The quotient rule needs f′g−fg′ over g²; separate derivative division is invalid."],
  ["For 100/q, why is the slope negative when q>0?","The same fixed cost is spread over more units."],
  ["What denominator condition is essential?","g must be nonzero in the region being studied."],
  ["Differentiate x/(x+1).","[(x+1)−x]/(x+1)² = 1/(x+1)², for x≠−1."],
  ["Average cost falls, but total cost rises. Is that contradictory?","No. More output can spread fixed costs while still adding positive variable costs."],
  "(f/g)′=(f′g−fg′)/g²",[check("-100/10**2",-1)]);
C("calc-chain-rule",4,"Derivative techniques","Chain rule",
  "The chain rule differentiates a function applied to another changing function.",
  "It tracks how one variable affects an intermediate quantity and then the result.",
  "d f(g(x))/dx = f′(g(x))g′(x).",
  "Turning one gear turns the next; the total response multiplies the two rates.",
  ["Differentiate f(x)=(2x+1)².","2(2x+1)×2 = 4(2x+1)."],
  ["The derivative of (2x+1)² is written 2(2x+1). What is missing?","The inner derivative 2; the result is 4(2x+1)."],
  ["How does differentiating x² differ from differentiating (2x)²?","The second includes the inner rate 2 and becomes 8x, versus 2x."],
  ["What must be tracked when applying the chain rule?","The inner and outer functions, their derivatives and valid domains."],
  ["If revenue grows €3 per user and users grow 5 per day, what is revenue's implied time rate?","€3/user × 5 users/day = €15/day, under the local model."],
  ["Can this derivative chain alone prove that an ad caused user growth?","No. A mathematical response model still needs causal evidence for its inputs."],
  "(f∘g)′(x)=f′(g(x))g′(x)",[check("3*5",15)]);
C("calc-exponential-rule",4,"Derivative techniques","Exponential derivative",
  "An exponential function has a growth rate proportional to its current size.",
  "It models smooth compounding and some early growth processes.",
  "For y=Aeʳᵗ, dy/dt=rAeʳᵗ=ry.",
  "A bigger snowball gathers more snow at the same relative growth rate.",
  ["A continuous-growth model has y=1,000 and rate r=0.02/day. Its current growth rate?","0.02 × 1,000 = 20 units/day."],
  ["A 2% continuous growth parameter guarantees adding 20 units daily forever. What is wrong?","The absolute growth rate rises with y; 20/day applies only at y=1,000."],
  ["What happens to y′ when r is negative?","y′ is negative for positive y; the model represents exponential decay."],
  ["What units belong to r in eʳᵗ?","Inverse time units, so rt has no units."],
  ["Differentiate y=e³ˣ.","y′=3e³ˣ by the chain rule."],
  ["Why can indefinite exponential customer growth be unrealistic?","Markets, capacity and competition impose limits; the model can fit only a suitable range."],
  "d(Aeʳᵗ)/dt=rAeʳᵗ",[check(".02*1000",20)]);
C("calc-log-rule",4,"Derivative techniques","Logarithmic derivative",
  "The natural logarithm's derivative at a positive input is its reciprocal.",
  "Logarithms connect absolute changes with proportional growth.",
  "d ln(x)/dx=1/x for x>0; d ln(y(t))/dt=y′(t)/y(t) for positive differentiable y.",
  "The same €1 increase is a much larger relative move from €10 than from €100.",
  ["What is the derivative of ln(x) at x=4?","1/4=0.25."],
  ["ln(x) is evaluated for x=−2 in real-valued growth calculations. What is wrong?","The real natural logarithm requires a positive input."],
  ["At y=100 and y′=5/day, what is d ln(y)/dt?","5/100 = 0.05/day, a 5% instantaneous relative rate."],
  ["What must be positive when computing a log growth rate?","The level y; zero or negative levels need a different treatment."],
  ["Differentiate ln(2x) for x>0.","(1/(2x))×2 = 1/x."],
  ["Is a finite 10% increase exactly a log return of 0.10?","No. ln(1.10)≈0.09531; 0.10 is a small-change approximation."],
  "d ln(x)/dx=1/x; d ln(y)/dt=y′/y",[check("Math.log(1.1)",0.09531017980432493)]);

// Band 5: approximation, tails, and optimization.
P("prob-standardize",5,"Continuous distributions","Standard score",
  "A standard score expresses a value's distance from the mean in SD units.",
  "It compares positions across measurements with different scales.",
  "z=(x−μ)/σ, for σ>0; normal probabilities require an appropriate normal model.",
  "Measure distance in typical-variation steps rather than the original units.",
  ["A value is 130 with mean 100 and SD 15. What is z?","(130−100)/15=2: two SD above the mean."],
  ["A z-score of 2 is automatically a 2% probability. What is wrong?","z is a standardized distance, not a probability; a distribution model supplies tail probabilities."],
  ["Scores 70 with mean 50/SD10 and 140 with mean100/SD20 have which z-scores?","Both have z=2 despite different original scales."],
  ["What assumption is needed to turn z into a standard normal tail chance?","The relevant distribution must be normal or well approximated by it."],
  ["A return of −8% has modeled mean 0% and SD 4%. Its z-score?","−8/4=−2."],
  ["A heavy-tailed series has many z=−3 days. Does standardizing fix its nonnormality?","No. Rescaling does not change tail shape."],
  "z=(x−μ)/σ",[check("(130-100)/15",2)]);
P("prob-lognormal",5,"Continuous distributions","Lognormal model",
  "A positive variable is lognormal when its natural logarithm follows a normal distribution.",
  "It models some multiplicative outcomes and right-skewed positive quantities.",
  "If ln(X) is normal with mean μ and variance σ², median X=e^μ and mean X=e^(μ+σ²/2).",
  "Repeated growth multipliers add on the log scale but multiply on the original scale.",
  ["ln(X) is normal with μ=0 and σ²=1. What are median and mean X?","Median e⁰=1; mean e⁰·⁵≈1.649."],
  ["A lognormal variable is allowed to be negative. What is wrong?","A standard lognormal variable is strictly positive."],
  ["Why does its mean exceed its median when σ>0?","The long right tail pulls the mean upward."],
  ["What should be checked before fitting lognormal losses?","Positivity, the log-scale fit and whether observed extreme tails match the model."],
  ["If ln(X) has μ=ln(100), what is the median X?","e^ln(100)=100."],
  ["Do multiplicative outcomes automatically have a lognormal distribution?","No. The log increments must support a normal approximation; dependence or heavy tails can defeat it."],
  "median X=e^μ; E[X]=e^(μ+σ²/2)",[check("Math.exp(.5)",1.6487212707001282)]);
P("prob-memoryless",5,"Continuous distributions","Memoryless waiting",
  "A memoryless waiting model has the same remaining waiting distribution after any elapsed wait.",
  "It clarifies why some random arrival processes do not become due.",
  "For exponential T, P(T>s+t | T>s)=P(T>t).",
  "A constant-rate random clock has no aging memory.",
  ["Exponential waiting has rate 1/hour. After already waiting 2 hours, chance of waiting more than 1 extra hour?","e⁻¹≈36.79%, the same as at the start."],
  ["A memoryless wait becomes more likely to end merely because it has lasted longer. What is wrong?","Its conditional remaining distribution is unchanged under this model."],
  ["Does a scheduled bus generally have memoryless waiting?","No. A schedule and elapsed time affect the remaining wait."],
  ["What evidence supports using memorylessness?","A roughly constant event hazard, without aging, schedule or state dependence."],
  ["For rate 2/minute, expected remaining wait after an unusually long wait?","Still 1/2 minute under the exponential model."],
  ["Why should machine aging not be ignored merely for simpler calculations?","A rising failure hazard changes remaining-life probabilities; memorylessness would misstate risk."],
  "P(T>s+t | T>s)=e⁻λt",[check("Math.exp(-1)",0.36787944117144233)]);
P("prob-beta",5,"Continuous distributions","Beta probability model",
  "A beta distribution is a flexible continuous model on the probability range 0 to 1.",
  "It represents uncertainty about a success probability rather than one binary outcome.",
  "With positive parameters α,β, its mean is α/(α+β).",
  "A curve over possible conversion rates shows which rates are more plausible.",
  ["A beta model has α=3 and β=7. What is its mean probability?","3/(3+7)=30%."],
  ["A beta-distributed p is treated as the next 0/1 result itself. What is wrong?","p is a possible success probability; a Bernoulli outcome is a separate 0/1 variable."],
  ["How does Beta(1,1) look on [0,1]?","It is uniform: every equal-width interval has equal probability."],
  ["What must be stated when using a beta distribution as a prior?","The parameter values and what prior knowledge or choice they represent."],
  ["Beta(2,2) and Beta(20,20) have what mean?","Both 50%, but Beta(20,20) is more concentrated around 50%."],
  ["Why does a concentrated prior deserve checking with sparse data?","It can strongly influence the posterior; assess whether its confidence is justified."],
  "E[p]=α/(α+β), α>0, β>0",[check("3/(3+7)",.3)]);
P("prob-large-numbers",5,"Repeated trials","Law of large numbers",
  "Under suitable conditions, averages approach the underlying expectation as the sample grows.",
  "It explains why repeated decisions can reveal a stable average edge.",
  "For independent identically distributed observations with finite mean, sample means converge to the population mean.",
  "Random bumps average out across many comparable draws, not through a forced compensating streak.",
  ["A stable independent 60% win process runs 10,000 trials. Expected wins?","10,000 × 0.6 = 6,000; the actual count still fluctuates."],
  ["After losses, wins must catch up to the expected total. What is wrong?","The theorem concerns long-run proportions; it does not force corrective outcomes."],
  ["Can the absolute win-count deviation grow while its fraction shrinks?","Yes. Count fluctuations can grow while becoming small relative to sample size."],
  ["What can break a simple repeated-trial interpretation?","Changing probabilities, dependence, selection bias, or a nonexistent finite mean."],
  ["Why does 6 wins in 10 trials provide less stable evidence than 6,000 in 10,000?","The larger comparable sample usually has less relative random fluctuation."],
  ["Does collecting more biased observations automatically reveal the target population mean?","No. More data can precisely estimate the wrong population."],
  "sample mean → E[X] under suitable assumptions",[check("10000*.6",6000)]);
P("prob-central-limit",5,"Repeated trials","Central limit approximation",
  "Under suitable conditions, standardized averages become approximately normal as sample size grows.",
  "It helps quantify uncertainty of averages without assuming individual values are normal.",
  "For iid observations with finite variance σ², SD(sample mean)=σ/√n.",
  "Many small independent bumps combine into a more regular bell-shaped average.",
  ["Individual SD is 10 and n=100 independent observations. What is the mean's SD?","10/√100=1."],
  ["The central limit theorem says the original observations become normal. What is wrong?","It concerns the distribution of their standardized average, not the raw values."],
  ["Increasing n from 100 to 400 changes the mean's SD how?","From 1 to 0.5, a 50% reduction."],
  ["Why can strong dependence or infinite variance invalidate the basic approximation?","They violate assumptions behind the usual √n scaling and normal limit."],
  ["At individual SD 12 and n=36, what is the mean's SD?","12/√36=2."],
  ["Is n=30 a universal guarantee of an accurate normal tail approximation?","No. Skewness, tails, dependence and the desired tail probability matter."],
  "SE(mean)=σ/√n under iid finite-variance sampling",[check("10/Math.sqrt(100)",1)]);
P("prob-heavy-tails",5,"Tail risk","Heavy tails",
  "A heavy tail assigns more chance to very extreme values than a light-tailed model.",
  "It highlights risks that a normal approximation may severely understate.",
  "Compare tail probabilities, not only means and standard deviations.",
  "Most days look calm, but occasional waves are much larger than a bell curve predicts.",
  ["Two models both average zero; one assigns 0.1% to a huge loss and the other 1%. How do those tail chances compare?","The second is ten times as large: 1%/0.1%=10."],
  ["Equal mean and SD are claimed to guarantee equal crash probabilities. What is wrong?","Distributions can share those summaries but have different tails."],
  ["Does 'heavy-tailed' necessarily mean infinite variance?","No. Some heavy-tailed distributions have finite variance; others do not."],
  ["What data deserve special attention in a tail model?","Extreme observations, missing disasters, dependence and uncertainty from having few tail events."],
  ["A 1% severe-loss chance is applied to 1,000 comparable cases. Expected severe losses?","1,000 × 0.01 = 10, without promising their timing."],
  ["Why can a quiet recent sample understate long-run tail risk?","Rare extremes may be absent from a short sample; absence is weak evidence of impossibility."],
  "",[check(".01/.001",10)]);
P("prob-power-law",5,"Tail risk","Power-law tail",
  "A power-law tail declines as a fixed power of the threshold.",
  "It shows how rare large outcomes can remain material at much higher thresholds.",
  "For a Pareto tail, P(X>x)=(xmin/x)^α for x≥xmin and α>0.",
  "Doubling the threshold cuts a power-law chance by a constant factor, rather than almost eliminating it.",
  ["A Pareto tail has xmin=1 and α=2. What is P(X>10)?","(1/10)²=1%."],
  ["A straight-looking log-log plot is called proof of a power law. What is wrong?","Other distributions can look similar; fit, goodness-of-fit tests and alternatives matter."],
  ["For the same α=2 tail, how does P(X>20) compare with P(X>10)?","0.25% versus 1%; doubling the threshold cuts the chance by 75%."],
  ["What threshold choice must be justified when fitting a power law?","The lower cutoff xmin where the tail model plausibly begins."],
  ["For this Pareto parameterization, when are mean and variance finite?","Mean requires α>1; variance requires α>2."],
  ["Why is α near 2 especially important when assessing variance?","Small parameter uncertainty can cross the finite-variance boundary; ordinary SD-based risk summaries become fragile."],
  "P(X>x)=(xmin/x)^α",[check("(1/10)**2",.01)]);
C("calc-curvature",5,"Optimization","Second derivative",
  "A second derivative measures how the first derivative changes.",
  "It distinguishes increasing marginal costs from diminishing returns.",
  "f″(x)>0 means the slope increases locally; f″(x)<0 means it decreases.",
  "A rising hill can become steeper or flatten even while still rising.",
  ["For f(x)=x², what is f″(x)?","f′(x)=2x, so f″(x)=2."],
  ["Positive second derivative is said to guarantee positive first derivative. What is wrong?","The slope can be negative but increasing; curvature does not determine its sign."],
  ["For f(x)=−x² at x=−1, compare slope and curvature.","f′(−1)=2 is positive; f″=−2 is negative."],
  ["What distinction must be kept when interpreting f″?","Changing slope versus the current slope or level."],
  ["C(q)=q³ for q>0. How does marginal cost change as q rises?","C′=3q² and C″=6q>0, so marginal cost increases."],
  ["Why can diminishing marginal revenue coexist with increasing total revenue?","Revenue can keep rising while each extra unit adds less than the previous unit."],
  "f″(x)=d f′(x)/dx",[check("-2*(-1)",2)]);
C("calc-stationary",5,"Optimization","Stationary point",
  "A stationary point has derivative zero.",
  "It identifies candidates for smooth interior optima.",
  "Solve f′(x)=0, then test the candidate rather than assuming it is a maximum.",
  "A flat patch can be a summit, a valley or just a brief flattening.",
  ["For f(x)=x²−4x, where is the stationary point?","f′=2x−4=0 gives x=2."],
  ["Every zero derivative is declared a maximum. What is wrong?","It may be a minimum or neither."],
  ["For x³ at x=0, is the stationary point a maximum or minimum?","Neither; the function rises through the point despite zero slope."],
  ["What extra locations must an optimization search consider?","Boundaries and points where the derivative does not exist."],
  ["Profit π(q)=10q−q². Its stationary quantity?","π′=10−2q=0 gives q=5."],
  ["If the feasible interval is q∈[0,3], may you choose the stationary q=5?","No. It is infeasible; optimize within the allowed interval."],
  "interior differentiable optimum candidate: f′(x)=0",[check("10/2",5)]);
C("calc-extremum-test",5,"Optimization","Testing an optimum",
  "The derivative's sign around a stationary point distinguishes local peaks and valleys.",
  "It prevents choosing a stationary loss instead of a profit maximum.",
  "A + to − slope change gives a local maximum; − to + gives a local minimum.",
  "A summit rises before it and falls after it.",
  ["For π(q)=10q−q², is q=5 a local maximum?","Yes. π″=−2<0, or π′ changes from positive to negative."],
  ["f″(a)=0 is called proof that no extremum exists. What is wrong?","The second-derivative test is inconclusive at zero; use other evidence."],
  ["For x⁴ at 0, what happens despite f″(0)=0?","It has a minimum: values on both sides are nonnegative and exceed f(0)=0."],
  ["What does f″(a)<0 establish at a stationary point?","A strict local maximum when the standard smoothness conditions apply, not necessarily a global maximum."],
  ["What is maximum profit for π(q)=10q−q² at q=5?","10×5−5²=25 monetary units."],
  ["Why must an estimated profit optimum still be checked with real data?","The result optimizes the fitted model; demand, costs and uncertainty may differ in reality."],
  "f′(a)=0 and f″(a)<0 ⇒ local maximum",[check("10*5-5**2",25)]);
C("calc-boundaries",5,"Optimization","Boundary checks",
  "A feasible interval's best value may occur at an endpoint.",
  "It keeps budget and capacity constraints inside an optimization decision.",
  "For a continuous function on [a,b], compare endpoint values and interior critical candidates.",
  "The highest point on a short hill segment may be where the segment ends.",
  ["Maximize π(q)=10q−q² for 0≤q≤3. Where is the optimum?","The unconstrained peak 5 is outside; π rises through the interval, so q=3 with profit 21."],
  ["A constrained problem ignores its endpoints. What is wrong?","Endpoints can be the feasible optimum even without zero derivative."],
  ["Maximize f(x)=x on [0,1]. Must the derivative be zero at the maximum?","No. f′=1 everywhere; the maximum is at boundary x=1."],
  ["What conditions ensure a maximum exists on a closed bounded interval?","Continuity on the interval; then the extreme value theorem applies."],
  ["Minimize x² on [2,4]. Where is the minimum?","At x=2, giving 4; x=0 is outside the feasible interval."],
  ["Why should a production model include integer and capacity limits?","A mathematically optimal fraction or excessive quantity may be impossible to implement."],
  "compare f(a), f(b), and feasible critical values",[check("10*3-3**2",21)]);
C("calc-elasticity",5,"Economic derivatives","Elasticity",
  "Elasticity measures a local percentage response per percentage input change.",
  "It compares sensitivities across prices or quantities with different units.",
  "For positive x and nonzero y=f(x), elasticity=(dy/dx)(x/y).",
  "A 1% price rise causing about a 2% demand fall has elasticity −2.",
  ["Demand is Q(p)=100−2p. At p=20, what is price elasticity?","Q=60 and Q′=−2, so −2×20/60≈−0.667."],
  ["A demand slope of −2 is automatically called elasticity −2. What is wrong?","Slope uses units; elasticity rescales by p/Q."],
  ["What does elasticity −0.667 suggest for a small 1% price rise?","Approximately a 0.667% demand decrease locally."],
  ["Why should a local elasticity not be applied unchanged to a huge price change?","The elasticity can vary across the demand curve."],
  ["For Q(p)=100/p at p>0, what is elasticity?","Q′=−100/p²; multiplying by p/Q gives −1."],
  ["Demand elasticity is −1 locally. What is the first-order revenue response to a small price rise?","Approximately zero: the percentage price increase offsets the percentage quantity decrease."],
  "elasticity=f′(x)x/f(x)",[check("-2*20/60",-2/3)]);

// Band 6: counting, formal updates, and accumulation.
P("prob-combinations",6,"Counting outcomes","Combinations",
  "A combination counts a selection where order does not matter.",
  "It counts poker holdings and success locations in binomial calculations.",
  "C(n,k)=n!/[k!(n−k)!] for integers 0≤k≤n.",
  "Picking Alice then Bob gives the same pair as Bob then Alice.",
  ["How many unordered pairs can be selected from 5 items?","5×4/2=10."],
  ["Five items produce 5×4=20 unordered pairs. What is wrong?","Each pair was counted twice; divide by 2."],
  ["What distinguishes a combination from a permutation?","Combinations ignore order; permutations distinguish different orders."],
  ["What must be specified before counting selections?","Whether order matters, whether replacement is allowed and whether items are distinct."],
  ["How many unordered two-card holdings come from 52 distinct cards?","52×51/2=1,326."],
  ["Why does a binomial exact-k formula include C(n,k)?","The k successes can occupy that many different trial-position sets."],
  "C(n,k)=n!/[k!(n−k)!]",[check("52*51/2",1326)]);
P("prob-collisions",6,"Counting outcomes","At least one matching pair",
  "Collision probability is the chance that any pair among several independent draws matches.",
  "It explains why matching birthdays or repeated identifiers can occur surprisingly early.",
  "Calculate no collision first, then subtract its probability from 1.",
  "Every new arrival can match any earlier arrival; the number of pairs grows quickly.",
  ["Three independent users choose uniformly among 10 icons. Chance at least two choose the same icon?","1−(10/10)(9/10)(8/10)=28%."],
  ["Only the chance that everyone matches the first person is counted. What is missed?","Matches among other pairs also create a collision."],
  ["How many distinct pairs exist among 10 people?","10×9/2=45, not 10."],
  ["What assumptions support the simple collision product?","Independent uniform choices from the same finite set."],
  ["Two independent choices among 10 equally likely icons have what matching chance?","1/10=10%."],
  ["If one icon is strongly preferred, does the uniform collision formula stay exact?","No. Unequal choice probabilities alter the collision chance."],
  "P(collision)=1−∏ᵢ₌₀ⁿ⁻¹ (m−i)/m, n≤m",[check("1-1*.9*.8",.28)]);
P("prob-hypergeometric",6,"Discrete distributions","Hypergeometric count",
  "A hypergeometric variable counts successes when sampling without replacement from a finite population.",
  "It handles changing success chances after items are removed.",
  "With N items, K successes and n draws, E[X]=nK/N.",
  "Drawing cards changes the deck; the remaining mix depends on earlier draws.",
  ["A bag has 3 red and 2 blue balls. Two draws without replacement: chance both red?","(3/5)(2/4)=30%."],
  ["The same draw is modeled as two independent 60% successes. What is wrong?","Without replacement, the second chance changes; 36% is not the correct joint chance."],
  ["What is the expected red count in these two draws?","2×3/5=1.2 red balls."],
  ["What population quantities must a hypergeometric model specify?","Population size N, success count K, and sample size n≤N."],
  ["Sample 5 from 20 items, 4 defective. Expected defects?","5×4/20=1."],
  ["When may a binomial approximation become reasonable?","When the sample fraction is small enough that removing items barely changes the success chance."],
  "P(X=k)=C(K,k)C(N−K,n−k)/C(N,n)",[check("3/5*2/4",.3)]);
P("prob-sum-variance",6,"Combined uncertainty","Variance of a sum",
  "The variability of a total depends on individual variances and their covariance.",
  "It prevents understating combined portfolio or operational risk.",
  "Var(X+Y)=Var(X)+Var(Y)+2Cov(X,Y).",
  "Independent bumps partly average out; synchronized bumps reinforce each other.",
  ["Independent quantities have SDs 3 and 4. What is the total's SD?","√(3²+4²)=5, not 7."],
  ["Standard deviations are always added to get total SD. What is wrong?","Variances add only under zero covariance; SD then uses a square root."],
  ["If covariance is positive, how does total variance compare with the independent case?","It is larger by 2Cov(X,Y)."],
  ["What must be checked before dropping the covariance term?","Whether zero covariance is justified; independence is sufficient but not necessary."],
  ["Variances are 9 and 16, covariance is 6. What is total variance?","9+16+2×6=37."],
  ["Can two assets' positive correlation reduce their diversification benefit?","Yes. Shared movements increase combined variance compared with otherwise similar independent assets."],
  "Var(X+Y)=Var(X)+Var(Y)+2Cov(X,Y)",[check("Math.sqrt(3**2+4**2)",5)]);
P("prob-conditional-mean",6,"Combined uncertainty","Conditional expectation",
  "A conditional expectation is the average of a random quantity within a specified condition.",
  "It combines scenario outcomes without confusing rates and probabilities.",
  "E[X]=Σ P(group)E[X | group] for an exhaustive nonoverlapping grouping.",
  "Average each room first, then weight room averages by how many people enter.",
  ["Normal demand occurs 80% of the time with mean revenue €100; high demand occurs 20% with mean €300. Overall expected revenue?","0.8×100+0.2×300=€140."],
  ["The scenario means €100 and €300 are averaged equally. What is wrong?","The scenario weights are 80% and 20%, giving €140 rather than €200."],
  ["Does a conditional mean determine a scenario's full risk?","No. Outcomes inside the scenario can still vary."],
  ["What must be checked when combining scenario means?","Scenario probabilities sum to 1, categories do not overlap, and means use the same units."],
  ["Success probability is 30%, mean profit given success €50, otherwise −€10. Expected profit?","0.3×50+0.7×(−10)=€8."],
  ["Why can conditioning on customers who survived overstate lifetime value?","It excludes early departures and estimates a selected group's mean, not all acquired customers."],
  "E[X]=E[E[X | group]]",[check(".8*100+.2*300",140)]);
P("prob-bayes-formula",6,"Bayesian updating","Bayes formula",
  "Bayes' formula reverses a conditional probability using a prior and the evidence rate.",
  "It updates rare-event risks without swapping P(signal | event) and P(event | signal).",
  "Posterior = sensitivity×prior / [sensitivity×prior + false-positive rate×(1−prior)].",
  "The numerator counts genuine signals; the denominator counts every signal.",
  ["Prior defect chance is 2%, sensitivity 80%, false-positive rate 5%. Defect chance after a positive?","0.8×0.02/[0.8×0.02+0.05×0.98]≈24.62%."],
  ["The evidence denominator includes only true positives. What is wrong?","False positives also produce the observed signal and belong in the denominator."],
  ["What happens if sensitivity stays fixed and the base rate rises?","Positive predictive value rises, with the false-positive rate fixed."],
  ["When is a Bayes formula undefined for an observed signal?","When the model assigns that signal probability zero; the evidence model must be reconsidered."],
  ["Prior fraud is 10%, sensitivity 90%, false-positive rate 10%. Posterior fraud after positive?","0.09/(0.09+0.09)=50%."],
  ["Can a precise arithmetic posterior be misleading?","Yes. Incorrect prior or test rates produce a precisely calculated but unreliable posterior."],
  "P(A|B)=P(B|A)P(A)/P(B)",[check(".8*.02/(.8*.02+.05*.98)",0.24615384615384617)]);
P("prob-bayes-odds",6,"Bayesian updating","Likelihood ratios and odds",
  "A likelihood ratio compares how likely the evidence is under two hypotheses.",
  "It expresses how strongly a signal shifts prior odds.",
  "Posterior odds = prior odds × likelihood ratio; convert odds o to probability o/(1+o).",
  "Evidence multiplies the starting odds instead of replacing them.",
  ["Prior event probability is 10%, and a signal has likelihood ratio 3. Posterior probability?","Prior odds=1/9; posterior odds=1/3; probability=(1/3)/(1+1/3)=25%."],
  ["A likelihood ratio of 3 is called a 300% event probability. What is wrong?","It is a multiplier on odds, not a probability."],
  ["What does likelihood ratio 1 do to prior odds?","Nothing; the signal is equally likely under both hypotheses."],
  ["Before multiplying several evidence likelihood ratios, what must be checked?","Their conditional dependence; multiplying marginal ratios can double-count related evidence."],
  ["Prior odds are 1 to 4 and LR is 2. What are posterior odds and probability?","Odds 1 to 2; probability 1/3≈33.33%."],
  ["Two reports repeat the same original result. Should they be treated as independent signals?","No. Shared information is not two independent pieces of evidence."],
  "posterior odds=prior odds×LR",[check("(1/9*3)/(1+1/9*3)",.25)]);
C("calc-integral-picture",6,"Integration","Integral as accumulation",
  "An integral adds a changing rate over an interval.",
  "It turns flow rates into total distance, cost or volume.",
  "Approximate total as the sum of rate×small interval width; the integral is the limiting total.",
  "Many thin area strips form the area under a rate curve.",
  ["Water flows at 3 liters/minute for 5 minutes. Total volume?","3×5=15 liters."],
  ["A rate of 3 liters/minute is called a total of 3 liters without a duration. What is missing?","A time interval; rate must be accumulated over time."],
  ["How do a derivative and integral differ in purpose?","A derivative finds a local rate; an integral accumulates a rate."],
  ["What must match when multiplying a rate by an interval?","The interval units must cancel the rate's denominator."],
  ["Revenue rate is €10/hour for 2 hours, then €20/hour for 3. Total revenue?","10×2+20×3=€80."],
  ["Why is multiplying a single endpoint rate by total time inaccurate for a varying rate?","It treats the whole interval as if it had that endpoint's rate."],
  "accumulation=∫ₐᵇ rate(t)dt",[check("10*2+20*3",80)]);
C("calc-antiderivative",6,"Integration","Antiderivative",
  "An antiderivative is a function whose derivative gives the original function.",
  "It provides a way to accumulate common rates exactly.",
  "An indefinite integral includes a constant because differentiating any constant gives zero.",
  "Many starting balances can share the same deposit rate.",
  ["What is an antiderivative of 2x?","x²+C, because the derivative is 2x and C is any constant."],
  ["An indefinite integral is given without +C as the only possible answer. What is wrong?","All functions differing by a constant have the same derivative."],
  ["Compare derivatives of x² and x²+10.","Both are 2x; their levels differ by 10."],
  ["How can an antiderivative be checked?","Differentiate it and confirm the original integrand on the valid domain."],
  ["Integrate 3x² with respect to x.","x³+C."],
  ["A balance has rate 2t and starts at €5 when t=0. What is the balance model?","B(t)=t²+5 euros; the initial value determines C=5."],
  "∫xⁿdx=xⁿ⁺¹/(n+1)+C, n≠−1 on a valid domain",[check("0**2+5",5)]);
C("calc-fundamental",6,"Integration","Fundamental theorem",
  "For a continuous rate with antiderivative F, its definite integral is F(b)−F(a).",
  "It computes accumulated change from two endpoint evaluations.",
  "∫ₐᵇ f(x)dx = F(b)−F(a) when F′=f under the theorem's conditions.",
  "The odometer's ending reading minus its starting reading gives accumulated travel.",
  ["Compute ∫ from 0 to 3 of 2x dx.","Antiderivative x²; 3²−0²=9."],
  ["A definite integral is reported as F(b) alone. What is wrong?","Subtract F(a), the starting value."],
  ["Why does +C disappear in F(b)−F(a)?","The same constant is added at both endpoints and cancels."],
  ["What assumption supports the simple continuous-rate version of the theorem?","The integrand is continuous on the interval and F differentiates to it."],
  ["Integrate speed v(t)=2t meters/second from t=1 to t=3 seconds.","t² from 1 to 3 gives 9−1=8 meters."],
  ["Does an integral of net cash flow give ending balance directly?","It gives balance change; add the initial balance."],
  "∫ₐᵇ f(x)dx=F(b)−F(a)",[check("3**2-1**2",8)]);
C("calc-signed-area",6,"Integration","Signed area",
  "A definite integral counts area above the axis positively and below it negatively.",
  "It distinguishes net change from total activity.",
  "Integrate a signed rate for net change; integrate its absolute value for total magnitude.",
  "Deposits and withdrawals can cancel in net balance while both create activity.",
  ["Cash flow is +€10/day for 2 days, then −€10/day for 2. Net change?","€20−€20=€0."],
  ["A zero integral proves nothing happened. What is wrong?","Positive and negative changes may cancel."],
  ["For that cash-flow pattern, net change versus total absolute flow?","Net €0; total absolute flow €40."],
  ["What must be identified before interpreting an integral as total distance?","Whether velocity changes sign; distance uses absolute velocity."],
  ["Walk +3 meters then −2 meters. Displacement and distance?","Net displacement 1 meter; total distance 5 meters."],
  ["Why can equal net profits hide different trading costs?","More offsetting transactions can create fees and turnover despite the same net result."],
  "net=∫v(t)dt; total magnitude=∫|v(t)|dt",[check("10*2-10*2",0)]);
C("calc-density-integral",6,"Probability and calculus","Integrating a density",
  "Integrating a probability density over an interval gives its probability.",
  "It connects calculus with continuous risks and waiting times.",
  "P(a≤X≤b)=∫ₐᵇ f(x)dx; density must integrate to 1 over its support.",
  "A density curve's selected area is the fraction of chance inside that range.",
  ["Density f(x)=2x on [0,1]. What is P(X≤0.5)?","∫₀⁰·⁵2x dx=0.5²=25%."],
  ["At x=0.5 the density is 1, so the exact value has 100% probability. What is wrong?","Density height is not point probability; an exact point has probability 0 in this continuous model."],
  ["Under this density, which half has more chance: [0,0.5] or [0.5,1]?","The upper half: 75% versus 25%."],
  ["How can you verify that 2x on [0,1] is a valid density?","It is nonnegative and ∫₀¹2x dx=1."],
  ["For this density, what is E[X]?","∫₀¹x·2x dx=2/3≈0.667."],
  ["Why does computing E[X] require the extra x factor?","It weights each possible value by its probability density rather than only counting probability."],
  "E[X]=∫x f(x)dx",[check(".5**2",.25)]);

// Band 7: probability estimates, simulation, and multiple inputs.
P("prob-likelihood",7,"Bayesian updating","Likelihood",
  "Likelihood compares how well parameter choices explain the observed data.",
  "It helps estimate win probabilities without calling the likelihood a posterior probability.",
  "For independent binary data with s successes and f failures, likelihood is proportional to pˢ(1−p)ᶠ.",
  "Hold the observed results fixed and slide the proposed success probability.",
  ["For one observed success, compare likelihoods under p=20% and p=80%.","0.2 versus 0.8; the success is four times as likely under p=80%."],
  ["A likelihood of 0.8 is called an 80% probability that the parameter is true. What is wrong?","It is the data's probability under that parameter; a posterior also requires a prior and normalization."],
  ["For one success and one failure, compare p=0.5 versus p=0.8 likelihoods.","0.5×0.5=0.25 versus 0.8×0.2=0.16; the first is larger."],
  ["What assumption supports multiplying separate outcome probabilities?","Conditional independence given the proposed model parameters."],
  ["There are 6 wins and 4 losses under a constant-p model. What is the maximum-likelihood p?","6/10=60%, but uncertainty remains."],
  ["Why can selecting the best model from many candidates overstate its predictive performance?","The selection can exploit random sample patterns; evaluate on fresh data."],
  "L(p)∝pˢ(1−p)ᶠ",[check(".8/.2",4)]);
P("prob-calibration",7,"Forecast evaluation","Probability calibration",
  "A forecast is calibrated when events assigned a given probability happen at roughly that frequency.",
  "It checks whether claimed 70% opportunities behave like 70% opportunities.",
  "Compare observed event frequency with predicted probability in comparable held-out groups.",
  "A '70%' box should contain about 70 successes per 100 cases over many cases.",
  ["A model gives 100 comparable events 70% probabilities; 50 happen. What is the observed rate?","50/100=50%, 20 percentage points below the forecast."],
  ["One 90% prediction fails, proving the model is uncalibrated. What is wrong?","Even a calibrated 90% prediction can fail; calibration needs many predictions and uncertainty checks."],
  ["Is a calibrated constant 50% model necessarily informative?","No. Calibration alone does not show it distinguishes easier from harder cases."],
  ["What data should be used to assess forecast calibration honestly?","Held-out comparable outcomes, without using the same observations to tune and judge the model."],
  ["Among 200 predictions at 25%, 50 events occur. Observed calibration rate?","50/200=25%, matching this bin's forecast rate."],
  ["Why should small calibration bins not be treated as exact evidence?","Their observed rates fluctuate; use uncertainty and adequate sample sizes."],
  "calibration: observed frequency ≈ predicted probability",[check(".7-.5",.2)]);
P("prob-brier",7,"Forecast evaluation","Brier score",
  "The Brier score averages squared errors between predicted probabilities and binary outcomes.",
  "It evaluates probability forecasts without reducing them to win/lose accuracy.",
  "For outcomes y∈{0,1}, score=(1/n)Σ(p−y)²; lower is better.",
  "A confident wrong prediction gets a larger penalty than a cautious wrong prediction.",
  ["A 0.8 prediction is followed by success y=1. Its Brier loss?","(0.8−1)²=0.04."],
  ["A forecast is judged only by whether its probability exceeded 50%. What information is lost?","Its confidence; 51% and 99% predictions would be treated equally despite very different calibration risks."],
  ["For a failed event, compare forecasts p=0.8 and p=0.2.","Brier losses 0.64 and 0.04; the confident wrong forecast is penalized more."],
  ["What must remain consistent when comparing two Brier scores?","The held-out events, outcome definition and weighting."],
  ["Two forecasts p=0.8,0.2 have outcomes 1,0. Mean Brier score?","(0.04+0.04)/2=0.04."],
  ["Does a lower Brier score automatically imply higher trading profit?","No. Trading also depends on payouts, costs, stakes and which opportunities are acted on."],
  "BS=(1/n)Σ(pᵢ−yᵢ)²",[check("(.8-1)**2",.04)]);
P("prob-beta-update",7,"Bayesian updating","Beta-binomial update",
  "A beta prior with independent Bernoulli data gives a beta posterior.",
  "It makes probability updating transparent with success and failure counts.",
  "Beta(α,β) plus s successes and f failures becomes Beta(α+s,β+f).",
  "Add success and failure evidence to two starting piles.",
  ["A Beta(1,1) prior observes 8 successes and 2 failures. Posterior mean p?","Beta(9,3) gives 9/12=75%."],
  ["Eight wins out of ten prove p=80% exactly. What is wrong?","The probability remains uncertain; a posterior distribution describes that uncertainty."],
  ["Why is this posterior mean 75% rather than the observed 80%?","The prior contributes one to each count, pulling the estimate toward 50%."],
  ["What assumptions support this simple update?","A common fixed p and outcomes independent conditional on p, plus the chosen beta prior."],
  ["Beta(2,2) prior with 3 successes and 1 failure gives what posterior?","Beta(5,3), mean 5/8=62.5%."],
  ["Why should repeated trials from one correlated user not blindly count as independent evidence?","They can overstate effective information and make the posterior too concentrated."],
  "p|data∼Beta(α+s,β+f)",[check("9/12",.75)]);
P("prob-predictive",7,"Bayesian updating","Posterior predictive uncertainty",
  "A posterior predictive distribution combines outcome randomness with uncertainty about model parameters.",
  "It forecasts new results rather than only estimating a parameter.",
  "Average each possible parameter's outcome distribution using its posterior weight.",
  "First pick a plausible rate, then draw an outcome at that rate.",
  ["A posterior assigns equal weight to p=20% and p=60%. Predictive probability of one success?","0.5×0.2+0.5×0.6=40%."],
  ["The same uncertain rate is reused for two trials, but success chance is set to 0.4². What is missed?","Shared parameter uncertainty: P(both)=0.5×0.2²+0.5×0.6²=20%, not 16%."],
  ["Parameter interval versus predictive interval: which also includes future outcome noise?","The predictive interval; uncertainty about the parameter alone is narrower in many common models."],
  ["What should posterior predictive checks compare?","Simulated and observed features such as spread, tails and counts, not only fitted means."],
  ["Why can a model fit the average count yet fail predictive checks?","It may misrepresent dispersion or extreme counts."],
  ["Does an excellent in-sample predictive check prove future validity?","No. New populations, time changes or omitted mechanisms can still cause failure."],
  "p(new data|data)=∫p(new data|θ)p(θ|data)dθ",[check(".5*.2**2+.5*.6**2",.2)]);
P("prob-monte-carlo",7,"Simulation","Monte Carlo estimate",
  "Monte Carlo simulation estimates probabilities or averages using repeated random draws from a model.",
  "It explores outcomes too complicated to calculate by hand.",
  "Estimate an event chance as event count divided by simulation count.",
  "Run many pretend futures, each obeying explicitly stated rules.",
  ["A model simulates 10,000 paths and 600 exceed a loss limit. Estimated breach chance?","600/10,000=6%."],
  ["One million simulated paths prove the model matches reality. What is wrong?","More simulation reduces simulation noise, not errors in assumptions or estimated parameters."],
  ["What differs between random simulation noise and model error?","Noise comes from a finite number of draws; model error comes from inaccurate rules or inputs."],
  ["What inputs should a risk simulation include?","Relevant outcome distributions, dependencies, costs, position rules and parameter uncertainty."],
  ["A simulation's average net profit is €2 across 100,000 draws. Does every draw earn €2?","No. Inspect the full outcome and drawdown distributions."],
  ["Why use a fixed random seed during development?","It makes a run reproducible; it does not improve the model's truth."],
  "Monte Carlo p̂ = event count/N",[check("600/10000",.06)]);
P("prob-mc-error",7,"Simulation","Monte Carlo precision",
  "A simulated proportion has sampling noise even when the model is fixed.",
  "It shows how many draws are needed for a reasonably stable estimate.",
  "For independent simulation draws, SE(p̂)≈√[p̂(1−p̂)/N].",
  "A bigger bucket of simulated outcomes makes random proportions steadier.",
  ["At p̂=0.5 with 10,000 independent draws, what is the simulated proportion's SE?","√(0.25/10,000)=0.005, or 0.5 percentage points."],
  ["Doubling simulation draws is said to halve SE. What is wrong?","SE scales as 1/√N; four times as many independent draws halves it."],
  ["10,000 versus 40,000 draws at p̂=50%: compare SE.","0.5 versus 0.25 percentage points; a 50% reduction."],
  ["What must be checked for correlated Monte Carlo chains?","Effective sample size; raw iteration count can greatly overstate independent information."],
  ["Zero rare events appear in 100 simulations. Is the event impossible?","No. The run may be too small to encounter a rare event."],
  ["Why can a tiny tail chance need many more simulations than a central average?","Rare events produce few observations, so their relative sampling error stays large."],
  "SE(p̂)≈√[p̂(1−p̂)/N]",[check("Math.sqrt(.5*.5/10000)",.005)]);
P("prob-markov-bound",7,"Probability bounds","A conservative probability bound",
  "For a nonnegative random quantity, its mean puts an upper bound on a large-outcome chance.",
  "It provides a rough check when a full distribution is unavailable.",
  "Markov: P(X≥a)≤E[X]/a for a>0 and X≥0.",
  "A small average cannot support too many huge nonnegative values.",
  ["A nonnegative loss has mean €10. What upper bound does Markov give for loss at least €100?","10/100=10%."],
  ["The 10% bound is treated as the exact loss probability. What is wrong?","It is only an upper bound and can be very loose."],
  ["Can Markov's nonnegative version be applied directly to signed profit?","No. Its nonnegativity condition must hold."],
  ["What assumptions does this bound need?","A nonnegative quantity, a positive threshold and a finite known mean."],
  ["Expected nonnegative delay is 2 days. Bound for delay at least 8 days?","2/8=25%."],
  ["A calculated bound is 150%. How should it be interpreted?","Use at most 100%; the bound gives no useful improvement over the trivial limit."],
  "P(X≥a)≤E[X]/a",[check("10/100",.1)]);
C("calc-partial",7,"Multivariable calculus","Partial derivative",
  "A partial derivative changes one input while holding the other inputs fixed.",
  "It separates price, marketing and quantity effects in a model.",
  "For ∂f/∂x, treat other independent inputs as constants.",
  "Move east on a hill without moving north.",
  ["For f(x,y)=x²+3y, what is ∂f/∂x at x=2?","2x=4; y is held fixed."],
  ["The y term is differentiated as if y changed with x in a partial derivative. What is wrong?","A partial derivative holds y fixed; linked inputs require a total derivative."],
  ["For f(x,y)=xy, compare the two partial derivatives.","∂f/∂x=y; ∂f/∂y=x."],
  ["What assumption is hidden in interpreting a partial derivative?","Other model inputs are held fixed, which may not be feasible in the real decision."],
  ["C(q,w)=wq+q². What is ∂C/∂q at q=5,w=3?","w+2q=3+10=13."],
  ["Why is a fitted price partial derivative not automatically a causal price effect?","Holding regressors fixed mathematically does not remove confounding or prove intervention behavior."],
  "∂f/∂x = local x-rate holding other inputs fixed",[check("3+2*5",13)]);
C("calc-gradient",7,"Multivariable calculus","Gradient",
  "The gradient is the vector containing a function's partial derivatives.",
  "It indicates which input directions increase the model fastest locally.",
  "∇f=(∂f/∂x,∂f/∂y,...); compare directions using consistently scaled inputs.",
  "A hill's steepest uphill arrow has both east and north components.",
  ["For f(x,y)=x²+y² at (1,2), what is the gradient?","(2x,2y)=(2,4)."],
  ["The gradient is treated as a guaranteed route to the global optimum. What is wrong?","It gives local information; constraints and other peaks or valleys matter."],
  ["Gradient ascent versus descent: what changes?","Ascent follows the gradient to increase a function; descent moves against it to decrease it."],
  ["Why do input units matter for gradient steps?","One unit of price and one unit of ad spend may have very different scales."],
  ["For f=3x+4y, which gradient vector is constant?","(3,4), everywhere."],
  ["What does a zero gradient identify?","A stationary candidate, possibly a minimum, maximum or saddle."],
  "∇f=(fₓ,fᵧ)",[check("2*2",4)]);
C("calc-directional",7,"Multivariable calculus","Directional derivative",
  "A directional derivative measures local change along a specified direction.",
  "It evaluates a feasible mix of input changes rather than one input alone.",
  "For a differentiable function and unit direction u, Dᵤf=∇f·u.",
  "A hill can rise steeply northward but be flat along a particular sideways path.",
  ["Gradient is (3,4), and unit direction is (1,0). What is the directional derivative?","3×1+4×0=3."],
  ["Direction (3,4) is used as a unit vector. What is wrong?","Its length is 5; the unit direction is (3/5,4/5)."],
  ["Along unit direction (3/5,4/5), what is the rate for gradient (3,4)?","3×3/5+4×4/5=5, the gradient's magnitude."],
  ["What should be checked before applying the gradient-dot-direction rule?","Differentiability and a correctly normalized direction in the chosen coordinate units."],
  ["Gradient (2,−2) and direction (1/√2,1/√2): what is the rate?","0; the two first-order contributions cancel."],
  ["Does zero first-order change guarantee the function stays constant along a finite move?","No. Curvature can produce a second-order change."],
  "Dᵤf=∇f·u, ||u||=1",[check("3*(3/5)+4*(4/5)",5)]);
C("calc-hessian",7,"Multivariable calculus","Curvature matrix",
  "A Hessian collects second partial derivatives and describes local curvature in multiple directions.",
  "It helps distinguish valleys, peaks and saddles around a stationary point.",
  "Positive-definite Hessian indicates a strict local minimum; negative-definite indicates a strict local maximum at a stationary point.",
  "A saddle rises one way and falls another, unlike a bowl.",
  ["For f(x,y)=x²+y², what is the Hessian?","A 2×2 matrix with diagonal 2,2 and off-diagonal 0."],
  ["A zero gradient alone proves a minimum in two dimensions. What is wrong?","The point may be a maximum or saddle; examine curvature or neighboring values."],
  ["For f=x²−y² at (0,0), what kind of stationary point exists?","A saddle: it rises along x and falls along y."],
  ["What does a semidefinite Hessian test sometimes fail to settle?","Whether a strict extremum exists; zero-curvature directions need further analysis."],
  ["For f=−x²−y², is the origin a local peak or valley?","A peak; both diagonal curvatures are −2."],
  ["Why might a noisy estimated Hessian be unreliable near a flat optimum?","Small errors can change the apparent curvature sign; assess numerical and model uncertainty."],
  "Hᵢⱼ=∂²f/(∂xᵢ∂xⱼ)",[check("2",2)]);
C("calc-total-change",7,"Multivariable calculus","Total differential",
  "A total differential adds first-order effects from all changing inputs.",
  "It estimates combined small changes in a business or risk model.",
  "Δf≈fₓΔx+fᵧΔy+... near the evaluation point.",
  "A bill changes from both the number of items and the price per item.",
  ["Revenue R=pq at p=10,q=100. Estimate the change for Δp=0.1 and Δq=2.","qΔp+pΔq = 100×0.1+10×2 = €30."],
  ["The same approximation is called exact for large simultaneous changes. What is missing?","Higher-order terms; here the exact extra interaction is ΔpΔq."],
  ["For this example, what is the exact revenue change?","10.1×102−10×100 = €30.20, €0.20 above the linear approximation."],
  ["When is the total differential most useful?","For small changes around a smooth, valid local model."],
  ["Cost sensitivities are €4/user and €2/ticket. Added 3 users and 5 tickets: approximate added cost?","4×3+2×5=€22."],
  ["If price affects quantity, why should both changes be included?","Holding quantity fixed misses its response; the total effect includes the quantity change too."],
  "Δf≈∇f·Δx",[check("10.1*102-10*100",30.2)]);

// Band 8: extremes, dependence, and constrained models.
P("prob-quantile",8,"Tail risk","Quantile threshold",
  "A quantile marks a level below which a stated share of a distribution lies.",
  "It translates risk probabilities into loss or delay thresholds.",
  "A p-quantile is a value where the cumulative chance reaches at least p.",
  "Find the cutoff line that leaves the desired probability area on its left.",
  ["A continuous loss model's 95th percentile is €100. What does that describe?","95% of modeled losses are at or below €100; 5% are above."],
  ["The 95th percentile is called the maximum possible loss. What is wrong?","The upper 5% can be larger, sometimes much larger."],
  ["Does the 95th percentile describe the average of the worst 5%?","No. That is a tail-average concept, such as expected shortfall under suitable definitions."],
  ["What details must accompany a loss quantile?","The probability level, time horizon, loss definition and model assumptions."],
  ["If 10,000 modeled losses have 500 above €100, what fraction exceeds that level?","500/10,000=5%."],
  ["Why can discrete outcomes complicate a quantile statement?","Probability masses can jump across the requested percentile, so threshold conventions matter."],
  "qₚ=inf{x:F(x)≥p}",[check("500/10000",.05)]);
P("prob-maximum",8,"Tail risk","Maximum of independent outcomes",
  "The largest of many outcomes is more likely to be extreme than one outcome.",
  "It accounts for multiple opportunities for record losses or unusual observations.",
  "For iid X₁,...,Xₙ with CDF F, P(max≤x)=F(x)ⁿ.",
  "A storm with many waves has more chances to contain one huge wave.",
  ["Each of 10 independent observations has a 1% exceedance chance. Chance at least one exceeds?","1−0.99¹⁰≈9.56%."],
  ["A 1% single-trade extreme chance is used unchanged for a 100-trade period. What is wrong?","The period contains many opportunities for an extreme."],
  ["Does independence matter for F(x)ⁿ?","Yes. Dependence changes the joint no-exceedance probability."],
  ["What must be fixed before interpreting a maximum probability?","The number of observations, their marginal distribution and dependence."],
  ["Two independent observations are below a threshold with 80% chance each. Chance both are below?","0.8²=64%; at least one above is 36%."],
  ["Why is a post-hoc record less surprising than a prespecified observation?","The record was selected from many observations, making extremes more likely."],
  "P(max Xᵢ>x)=1−F(x)ⁿ under iid sampling",[check("1-.99**10",0.09561792499119559)]);
P("prob-loss-sequence",8,"Repeated trials","Losing streak probability",
  "A specified sequence's chance multiplies its conditional step probabilities.",
  "It separates a fixed losing run from finding a run anywhere in a long history.",
  "For independent constant loss chance q, k prespecified losses have probability qᵏ.",
  "One chosen block is one target; a long timeline contains many overlapping blocks.",
  ["With independent 40% loss chance, what is the chance the next 3 trades all lose?","0.4³=6.4%."],
  ["The chance of any three-loss run in 100 trades is reported as 6.4%. What is wrong?","6.4% describes one specified block; many possible blocks increase the chance."],
  ["Does a three-loss streak prove a strategy's expected value is negative?","No. Positive-EV strategies can have losing streaks."],
  ["What must be checked before using qᵏ for trading losses?","Stable probabilities and independence; volatility regimes can cluster losses."],
  ["At 50% loss chance, what is the chance of four specified losses?","0.5⁴=6.25%."],
  ["Why should bankroll simulations consider streak location and withdrawals?","The same loss count can create different drawdowns and ruin risk depending on sequence and cash flows."],
  "P(k specified losses)=qᵏ under independence",[check(".4**3",.064)]);
P("prob-tail-dependence",8,"Combined uncertainty","Joint extreme risk",
  "Extreme outcomes can become more synchronized than typical daily moves suggest.",
  "It tests diversification when protection is needed most.",
  "Estimate joint loss chances using conditional extremes, not only average correlation.",
  "Several umbrellas can fail together in the same severe storm.",
  ["A has 5% crash chance; B crashes 40% of the time given A crashes. Chance both crash?","0.05×0.40=2%."],
  ["B's unconditional crash chance is 5%, so joint crash is forced to be 0.25%. What is wrong?","That product assumes independence; the given conditional chance yields 2%."],
  ["Compare 2% joint crashes with an independent 0.25% estimate.","2/0.25=8 times the joint risk."],
  ["What extra evidence helps assess crisis dependence?","Historical stress periods, structural shared exposures and plausible joint scenarios."],
  ["Can low average correlation prove low joint tail risk?","No. Dependence can vary across the distribution."],
  ["Why should several correlated bets not each receive a separately calculated full allocation?","Shared losses can concentrate total risk; sizing needs joint scenarios and capital constraints."],
  "P(A crash∩B crash)=P(A crash)P(B crash|A crash)",[check(".05*.4",.02)]);
P("prob-mixtures",8,"Modeling uncertainty","Mixture distribution",
  "A mixture combines different outcome distributions with scenario probabilities.",
  "It models changing customer groups or calm and stressed market regimes.",
  "Overall probabilities and expectations are weighted across component scenarios.",
  "One histogram blends two different populations rather than one homogeneous process.",
  ["A calm regime has 1% loss-limit chance; a stressed regime has 20%. Weights are 90% and 10%. Overall chance?","0.9×0.01+0.1×0.20=2.9%."],
  ["A mixture is replaced by one average regime and assumed to preserve every tail chance. What is wrong?","Matching a mean does not generally preserve dispersion, shape or tails."],
  ["Can a mixture of normal components be nonnormal overall?","Yes. Different means or scales can create skew, multiple peaks or heavier-looking tails."],
  ["What must be checked about mixture weights?","They are nonnegative, sum to 1 and match the target population or period."],
  ["A customer mix moves toward the higher-converting group. Can overall conversion rise with unchanged group rates?","Yes; composition changes the weighted average."],
  ["Why might historical regime weights be unreliable in a new crisis?","The frequency and behavior of regimes can change; stress-test alternative weights."],
  "P(A)=ΣᵢwᵢP(A|regime i)",[check(".9*.01+.1*.2",.029)]);
P("prob-selection-conditioning",8,"Conditional probability","Conditioning on selection",
  "Selecting observations changes the group whose probabilities you are estimating.",
  "It prevents survivor or winner samples from being mistaken for all opportunities.",
  "State the selected condition and compare P(event|selected) with the target P(event).",
  "Looking only at race finishers misses runners who dropped out.",
  ["Out of 100 funds, 20 close. Of 80 survivors, 40 win. Observed survivor win rate?","40/80=50%; it is conditional on surviving."],
  ["A 50% survivor win rate is used as the all-fund win rate. What is wrong?","Closed funds were excluded; their outcomes are needed to estimate the full population."],
  ["If all 20 closed funds lost, what is the full win rate?","40/100=40%, 10 percentage points below the survivor rate."],
  ["What selection rules should a dataset disclose?","Inclusion, exclusion, survival and missing-data criteria."],
  ["A poker database records only winning sessions. Can it estimate long-run ROI?","No. Losing sessions are needed; the observed sample is selected."],
  ["Why can conditioning on a common consequence create a misleading association?","Selection can connect otherwise independent causes; the selected group's relationships need not reflect the whole population."],
  "",[check("40/80-40/100",.1)]);
P("prob-stopping-rule",8,"Repeated trials","A stopping rule changes the event",
  "Stopping when a favorable pattern appears makes that pattern part of the sampling process.",
  "It explains why a planned-run probability can misstate an adaptive experiment.",
  "Define whether the event is observed at a fixed time or at any time before stopping.",
  "Repeatedly checking a scoreboard gives many chances to catch one favorable moment.",
  ["Two independent 5% false-alarm checks are made, and any alarm counts. Chance at least one alarm?","1−0.95²=9.75%."],
  ["An analyst keeps checking until an ordinary fixed-sample threshold is crossed, then reports a 5% false-alarm rate. What is wrong?","The repeated-search procedure can have a larger false-alarm chance."],
  ["Are repeated interim checks generally independent?","No. Overlapping data make them dependent; a sequential method must account for the actual design."],
  ["What should be planned before an adaptive experiment?","A valid sequential procedure, stopping rules, outcomes and error control."],
  ["Does a properly specified Bayesian posterior mechanically require fixed sample size?","No, but model assumptions, selection mechanisms and the decision rule still require care."],
  ["Why does 'stop after a profit' not create a positive edge from a fair game?","Stopping changes the observed path, not the underlying per-play expectation; costs and possible large losses remain."],
  "P(any alarm)=1−(1−α)ⁿ for independent checks",[check("1-.95**2",.0975)]);
C("calc-constraint",8,"Constrained optimization","Feasible constraint",
  "A constraint limits which input combinations can actually be chosen.",
  "It keeps an optimum within budget, capacity and risk limits.",
  "Optimize the objective only over the feasible set.",
  "The best hilltop is irrelevant if it lies beyond a fence you cannot cross.",
  ["Maximize xy with x+y=10 and x,y≥0. What equal split maximizes the product?","x=y=5 gives product 25; substituting y=10−x gives x(10−x)."],
  ["The unrestricted optimum is chosen despite exceeding a €100 budget. What is wrong?","It is infeasible; the budget is part of the problem."],
  ["Equality versus inequality constraint: what differs?","Equality must hold exactly; inequality permits all values within its bound."],
  ["What must be checked when an optimum lies at a constraint boundary?","Whether other feasible boundary points or corners give a better value."],
  ["If x+y≤10 with nonnegative x,y, does x=y=5 remain optimal for xy?","Yes. The product is largest at the full-budget equal split."],
  ["Why might an uncertainty buffer change a budget optimum?","Estimated costs can exceed forecasts; a robust feasible allocation may leave room for errors."],
  "maximize f(x,y) subject to g(x,y)≤B",[check("5*5",25)]);
C("calc-lagrange",8,"Constrained optimization","Lagrange multiplier",
  "A Lagrange multiplier links an objective's gradient to an equality constraint's gradient.",
  "It finds smooth constrained candidates and interprets the marginal value of relaxing a limit.",
  "For f maximized subject to g=B, solve ∇f=λ∇g with g=B, then compare candidates.",
  "At an interior constrained optimum, no allowed sideways move can improve the objective to first order.",
  ["Maximize xy subject to x+y=10. What do the Lagrange equations imply?","y=λ and x=λ, so x=y=5."],
  ["Any solution to Lagrange equations is declared the global optimum. What is wrong?","It is a candidate; boundaries, other solutions and objective values must be checked."],
  ["At x=y=5, what is λ for this product objective?","λ=5: one extra budget unit locally raises the optimized product by about 5."],
  ["What regularity condition matters for the standard equality-constraint method?","The constraint gradient should be nonzero at the candidate."],
  ["With x+y=B, optimized xy is B²/4. Its derivative with respect to B at B=10?","B/2=5, matching the multiplier."],
  ["Why is a shadow price local rather than a promise for a large budget expansion?","The optimum and active constraints can change as the budget changes."],
  "∇f=λ∇g; g=B",[check("10/2",5)]);
C("calc-integral-expected",8,"Probability and calculus","Continuous expected value",
  "Continuous expected value integrates possible values weighted by their density.",
  "It estimates average continuous loss, delay or revenue from a full model.",
  "E[g(X)]=∫g(x)f(x)dx when the expectation exists.",
  "Each thin probability strip contributes its height times its outcome value.",
  ["X has density 2x on [0,1]. What is E[X²]?","∫₀¹x²·2x dx=∫₀¹2x³dx=1/2."],
  ["E[X²] is set equal to E[X]². What is wrong?","Nonlinear functions generally do not commute with expectation; here 1/2 differs from (2/3)²."],
  ["For this density, what is Var(X)?","E[X²]−E[X]²=1/2−4/9=1/18≈0.05556."],
  ["What must be checked before treating an integral as a finite expectation?","The relevant absolute expectation must be finite; heavy tails can make it diverge."],
  ["Uniform X on [0,2]: expected X?","∫₀²x×(1/2)dx=1."],
  ["Why can expected loss remain large even when most losses are small?","Large tail values are weighted by both their chance and magnitude."],
  "E[g(X)]=∫g(x)f(x)dx",[check(".5-(2/3)**2",1/18)]);
C("calc-exponential-equation",8,"Dynamic models","Differential equation",
  "A differential equation states a relationship involving a changing quantity and its rate.",
  "It models growth, decay and feedback over time.",
  "The proportional-rate equation y′=ry has solution y(t)=y(0)eʳᵗ.",
  "The rule tells the current direction and speed; integration traces the whole path.",
  ["A quantity starts at 100 and follows y′=0.1y per year. Value after one year?","100e⁰·¹≈110.52."],
  ["The equation y′=0.1y is treated as adding 10 units every year forever. What is wrong?","The increase is proportional to the changing level, not fixed."],
  ["How does y′=−ry with r>0 differ?","It describes exponential decay for a positive level."],
  ["What data are needed besides the rate equation for a unique trajectory?","An initial condition and suitable conditions for existence and uniqueness."],
  ["For y(0)=100 and r=−ln(2), value after one unit of time?","100e^−ln(2)=50."],
  ["Why should a dynamic model be validated against time-series behavior?","A plausible-looking equation can omit feedback, shocks or changing parameters."],
  "y′=ry; y(t)=y₀eʳᵗ",[check("100*Math.exp(.1)",110.51709180756477)]);
C("calc-logistic-growth",8,"Dynamic models","Capacity-limited growth",
  "Logistic growth slows as a growing quantity approaches a capacity limit.",
  "It contrasts unconstrained exponential growth with saturation.",
  "y′=ry(1−y/K), with r>0 and capacity K>0.",
  "Early growth is fast like compounding; near a full room there is little space left.",
  ["For r=0.1/day, K=1,000 and y=500, what is y′?","0.1×500×(1−0.5)=25 users/day."],
  ["A logistic model always adds the same number of users daily. What is wrong?","The growth rate depends on the current y and distance from capacity."],
  ["At y=K, what is the modeled growth rate?","0, because 1−y/K=0."],
  ["What model parameter deserves careful validation?","Capacity K; it is an assumption or estimate, not a fixed law of a real market."],
  ["For r=0.1,K=1,000, compare y′ at y=100 and y=900.","Both equal 9 users/day; one is small and the other nearly saturated."],
  ["Does reaching an estimated capacity prove future growth is impossible?","No. Capacity, products and markets can change; the model is conditional on K."],
  "y′=ry(1−y/K)",[check(".1*500*(1-500/1000)",25)]);

// Band 9: uncertainty inside models and numerical decisions.
P("prob-parameter-uncertainty",9,"Modeling uncertainty","An estimated probability is uncertain",
  "A fitted probability is an estimate, not a known physical constant.",
  "It prevents treating a small estimated edge as a sure advantage.",
  "Evaluate decisions across plausible parameter values as well as random outcomes.",
  "A blurry forecast is a range of possible weather maps, not one perfectly known map.",
  ["Even-money profit is +€100 or −€100. At p=55%, expected profit?","0.55×100−0.45×100=€10."],
  ["An estimated 55% win rate is treated as a guaranteed positive edge. What is wrong?","Estimation error can put the actual rate below the 50% break-even point."],
  ["If actual p is 45% instead, what is expected profit for the same payout?","0.45×100−0.55×100=−€10."],
  ["What evidence helps assess uncertainty about p?","Sample size, selection, calibration, changing conditions and a justified uncertainty model."],
  ["Estimated p is 51%, with plausible values 47% to 55%. Is the edge robust at even money?","No. That range crosses 50%, so plausible cases include negative EV."],
  ["Why can a smaller allocation be sensible despite a positive posterior mean edge?","Capital constraints and uncertainty can make full exposure fragile; compare losses across plausible scenarios."],
  "EV at even money = stake×(2p−1)",[check("100*(2*.55-1)",10)]);
P("prob-total-variance",9,"Combined uncertainty","Within and between variation",
  "Total variance includes average within-group variance plus variance between group means.",
  "It separates ordinary randomness from changing regimes or uncertain parameters.",
  "Var(X)=E[Var(X|Z)]+Var(E[X|Z]).",
  "People vary inside each room, and the room averages can differ too.",
  ["Two equally weighted regimes have means 0 and 10, each variance 4. Overall variance?","Overall mean 5; between variance 25; total 4+25=29."],
  ["Only the two within-regime variances are averaged. What is missed?","The extra variation caused by different regime means."],
  ["If every regime has the same mean, what happens to between-regime variance?","It is 0, but within-regime variation can remain."],
  ["What grouping assumptions are needed for this decomposition?","A valid joint distribution and finite second moments; no independence between X and Z is required."],
  ["How does shared uncertainty about a rate affect repeated predictions?","It can add dependence and between-parameter variation beyond ordinary outcome noise."],
  ["Why can one average-volatility estimate miss regime risk?","It may omit variation from changing levels, scales or parameters across regimes."],
  "Var(X)=E[Var(X|Z)]+Var(E[X|Z])",[check("4+.5*(0-5)**2+.5*(10-5)**2",29)]);
P("prob-many-requirements",9,"Combined uncertainty","Several conditions must hold",
  "A plan requiring many uncertain conditions succeeds only when their joint event occurs.",
  "It exposes fragile forecasts built from individually plausible assumptions.",
  "Multiply conditional chances along the full chain; use unconditional products only with independence.",
  "A long bridge fails if any necessary plank fails.",
  ["Ten independent conditions each have an 80% chance. Probability all hold?","0.8¹⁰≈10.74%."],
  ["Each assumption is 80% likely, so the whole ten-assumption plan is called 80% likely. What is wrong?","All conditions must hold jointly; their combined chance can be much smaller."],
  ["For two independent 80% conditions, what is the joint chance?","64%, 16 percentage points below either individual chance."],
  ["What should be checked when assumptions share one underlying cause?","Dependence; a shared cause can make the simple product wrong."],
  ["A project needs approval with 90% chance and success given approval with 60%. Overall success?","0.9×0.6=54%."],
  ["Why can counting alternative successful routes improve a project forecast?","The plan may succeed through more than one route; add mutually exclusive paths without double-counting overlaps."],
  "P(all)=P(A₁)P(A₂|A₁)...",[check(".8**10",0.10737418240000006)]);
P("prob-calibration-sharpness",9,"Forecast evaluation","Calibration versus discrimination",
  "Calibration checks probability honesty; discrimination checks whether the model separates easier from harder cases.",
  "A useful forecaster should be reliable and distinguish different risks.",
  "Compare calibration and proper-score performance on the same held-out population.",
  "Saying 50% for everyone can be honest but less useful than correctly separating 80% and 20% cases.",
  ["Half of cases truly have 80% success chance and half 20%. Is predicting 50% for every case calibrated overall?","Yes overall: the event frequency averages 50%, but the forecast loses subgroup information."],
  ["Perfect overall calibration is called proof of a powerful model. What is wrong?","A constant base-rate forecast can be calibrated without distinguishing individual risks."],
  ["Expected Brier loss for the informed 80%/20% model versus constant 50%?","0.16 versus 0.25; the informed model's expected loss is 36% lower."],
  ["What must be checked beyond one overall calibration number?","Subgroups, probability ranges, discrimination and sampling uncertainty."],
  ["Can more extreme probabilities improve sharpness but worsen reliability?","Yes. Confident probabilities can be badly miscalibrated."],
  ["A model ranks events well but overstates all probabilities. What needs repair?","Probability calibration; ranking quality alone is insufficient for stake sizing or expected-value calculations."],
  "relative Brier improvement=(baseline loss−model loss)/baseline loss",[check("(.25-.16)/.25",.36)]);
P("prob-zero-events",9,"Simulation","No observed rare events",
  "Zero observed events can still be compatible with a small nonzero event chance.",
  "It avoids declaring a tail risk impossible from a quiet sample.",
  "For n independent fixed-probability trials with zero events, a one-sided 95% upper bound is 1−0.05^(1/n), approximately 3/n.",
  "A small net may catch no rare fish without proving the lake has none.",
  ["Zero events occur in 1,000 independent trials. Approximate one-sided 95% upper bound for the event chance?","3/1,000=0.3%; the exact binomial bound is about 0.299%."],
  ["No crashes in 100 simulations is interpreted as zero crash probability. What is wrong?","Rare crashes may simply not appear in a small run."],
  ["With zero events, how does the approximate bound change from n=1,000 to n=10,000?","From 0.3% to 0.03%, a 90% reduction."],
  ["What assumptions support the binomial zero-event bound?","Independent comparable trials with the same fixed event probability."],
  ["Why can a million quiet simulations still miss real-world risks?","The model may exclude the relevant mechanism; the bound applies only to its simulated event process."],
  ["What does '95% upper bound' mean here?","It belongs to a repeated-sampling procedure with 95% coverage, not a 95% posterior probability without a prior."],
  "upper bound=1−α^(1/n), α=0.05",[check("1-.05**(1/1000)",0.0029912495450953314)]);
P("prob-mixture-sensitivity",9,"Modeling uncertainty","Scenario weight sensitivity",
  "Sensitivity analysis checks how an answer changes when assumed probabilities change.",
  "It shows whether a conclusion relies on one optimistic regime frequency.",
  "Recalculate the same outcome metric under several plausible weights.",
  "Move weight between the calm and stormy buckets and see how the forecast changes.",
  ["Normal loss-limit risk is 1%, crisis risk 30%. Crisis weight is 5%. Overall risk?","0.95×0.01+0.05×0.30=2.45%."],
  ["One historical 5% crisis weight is treated as permanently known. What is wrong?","Regime frequency is uncertain and may change."],
  ["If crisis weight doubles to 10%, what is overall risk?","0.90×0.01+0.10×0.30=3.9%, about 59.18% above 2.45%."],
  ["What quantities should a scenario sensitivity check vary?","Relevant probabilities, loss sizes, dependence and costs rather than only one convenient input."],
  ["If a conclusion flips across plausible weights, how should it be described?","It is assumption-sensitive; show the range and identify the threshold."],
  ["Why is a best-case simulation insufficient for capital planning?","It can hide scenarios with materially larger losses or binding liquidity constraints."],
  "risk(w)=(1−w)risk_normal+w risk_crisis",[check(".9*.01+.1*.3",.039)]);
P("prob-tail-model-fit",9,"Tail risk","Choosing a tail model",
  "Tail model choice should use fit diagnostics and alternatives, not visual appearance alone.",
  "It reduces false confidence in extrapolated extreme risks.",
  "Compare plausible families, cutoff choices and held-out or resampling diagnostics.",
  "Several roads can look straight nearby but curve differently beyond the visible stretch.",
  ["Two extremes appear among 10,000 observations. What is the empirical exceedance rate?","2/10,000=0.02%, with substantial uncertainty from only two events."],
  ["A fitted power law is declared certain because its log-log line looks straight. What is missing?","Goodness-of-fit assessment, competing models and uncertainty about the fitting range."],
  ["Why can a lognormal and power-law tail be hard to distinguish in small samples?","Both can produce very large values; few extremes provide weak evidence about asymptotic shape."],
  ["What must be disclosed before extrapolating far beyond observed losses?","Model family, tail cutoff, parameter uncertainty and how unsupported that extrapolation is."],
  ["Should the center of a distribution alone determine its crash model?","No. Central fit can be good while tail fit is poor."],
  ["How can stress testing help when tail models disagree?","Evaluate decisions across credible tail alternatives instead of hiding the disagreement inside one forecast."],
  "",[check("2/10000",.0002)]);
P("prob-ruin-walk",9,"Repeated decisions","Ruin in a simple random walk",
  "Ruin probability depends on the starting reserve, win chance and path, not only positive expected gain.",
  "A simple model shows why a profitable game can still bankrupt a small bankroll.",
  "With independent ±1 steps, p>1/2, no upper boundary and initial reserve i, eventual ruin probability is [(1−p)/p]ⁱ.",
  "A slightly uphill walk can still hit a nearby cliff before it moves safely away.",
  ["Unit win chance is 60% and starting reserve 10 units. Eventual ruin chance in the stated walk?","(0.4/0.6)¹⁰≈1.73%."],
  ["Positive expected gain is called proof that ruin is impossible. What is wrong?","Unfavorable sequences can exhaust a finite reserve even with an edge."],
  ["For a fair walk between 0 and 100 starting at 20, chance of hitting 0 first?","1−20/100=80%, under the fair-walk assumptions."],
  ["What makes this formula unsuitable as an automatic real-trading risk estimate?","Variable losses, changing edges, leverage, gaps, costs, finite horizons and position sizing violate its simple assumptions."],
  ["For the favorable unit walk, does increasing starting reserve reduce ruin probability?","Yes. The ratio is below 1, so raising its exponent decreases the result."],
  ["Why distinguish eventual ruin from ruin during the next 100 trials?","They have different horizons; an infinite-horizon result need not be the finite-period probability."],
  "P(eventual ruin)=[(1−p)/p]ⁱ for p>1/2 under the stated unit-walk model",[check("(.4/.6)**10",0.017341529915832633)]);
C("calc-finite-difference",9,"Numerical calculus","Finite differences",
  "A finite difference approximates a derivative using nearby function values.",
  "It checks formulas and estimates slopes when no symbolic derivative is available.",
  "Forward difference=[f(x+h)−f(x)]/h; central difference=[f(x+h)−f(x−h)]/(2h).",
  "Probe slightly on either side and compare the measured heights.",
  ["For f(x)=x² at x=2 and h=0.1, what is the central difference?","(2.1²−1.9²)/0.2=4."],
  ["Making h arbitrarily tiny is said to always improve numerical derivatives. What is wrong?","Subtraction cancellation and noisy values can amplify error at very small h."],
  ["For the same function and h, compare forward and central differences.","Forward 4.1; central 4, matching the exact derivative here."],
  ["What should be checked when testing a numerical derivative?","Several sensible step sizes, units, noise and domain boundaries."],
  ["A function is measured with random error. Why might larger steps sometimes help?","They reduce the relative impact of measurement noise, though they increase approximation bias."],
  ["Why can a central difference be impossible at a hard boundary?","One probe lies outside the allowed domain; use a valid one-sided scheme or reformulate."],
  "central difference=[f(x+h)−f(x−h)]/(2h)",[check("(2.1**2-1.9**2)/.2",4)]);
C("calc-numerical-integral",9,"Numerical calculus","Numerical integration",
  "Numerical integration approximates area by adding simple shapes.",
  "It accumulates rates or densities when an exact antiderivative is unavailable.",
  "Trapezoid area for one interval is width×(left height+right height)/2.",
  "Cover a curved region with small flat-sided pieces.",
  ["Approximate ∫₀¹x² dx with one trapezoid.","1×(0+1)/2=0.5; exact area is 1/3."],
  ["One trapezoid is called exact for every curve. What is wrong?","Curvature creates approximation error; refine the grid and check convergence."],
  ["With two equal trapezoids for x² on [0,1], what is the estimate?","0.5×(0+0.25)/2 + 0.5×(0.25+1)/2 = 0.375."],
  ["What diagnostics support a numerical integral?","Stable results as the grid or tolerance improves, plus checks for sharp peaks and tails."],
  ["Does integrating only a finite interval capture all probability of an unbounded density?","Not unless the omitted tail is negligible or separately accounted for."],
  ["Why can an apparently smooth plot hide integration difficulty?","A narrow peak or discontinuity can fall between coarse evaluation points."],
  "trapezoid=(b−a)[f(a)+f(b)]/2",[check(".5*(0+.25)/2+.5*(.25+1)/2",.375)]);
C("calc-gradient-step",9,"Numerical optimization","Gradient descent step",
  "Gradient descent moves against a function's gradient to reduce it locally.",
  "It trains many models by lowering a loss function.",
  "x_new=x_old−η∇f(x_old), with a suitable positive step size η.",
  "Walk downhill in small steps; an oversized stride can jump past the valley.",
  ["For f(x)=(x−3)², start x=0 and use η=0.1. Next x?","Gradient=−6; x_new=0−0.1×(−6)=0.6."],
  ["Any positive learning rate is claimed to make loss decrease. What is wrong?","A step can be too large and increase loss or diverge."],
  ["How does loss change in that step?","From 9 to (0.6−3)²=5.76, a 36% reduction."],
  ["What should be monitored during optimization?","Objective values, step sizes, gradient scale, constraints and convergence behavior."],
  ["For the same starting point but η=2, what happens?","New x=12; loss 81, nine times the original 9."],
  ["Does training loss convergence prove out-of-sample accuracy?","No. Optimization and generalization are different questions."],
  "xₜ₊₁=xₜ−η∇f(xₜ)",[check("0-.1*(-6)",.6)]);
C("calc-convexity",9,"Optimization","Convex objective",
  "A convex function lies below or on chords joining its points.",
  "For minimization, convexity prevents inferior local minima under suitable feasible constraints.",
  "A local minimum of a convex function on a convex feasible set is global.",
  "A bowl has no separate hidden lower valley.",
  ["Is f(x)=(x−3)² convex, and where is its global minimum?","Yes; f″=2>0, and x=3 gives 0."],
  ["Every nonlinear objective is labeled nonconvex. What is wrong?","Many curved functions, including squared distance, are convex."],
  ["Does convexity guarantee a unique minimizer?","No. Strict convexity gives at most one minimizer; a flat convex function can have many."],
  ["What besides the objective matters for a convex optimization claim?","The feasible set must be convex, and existence and other regularity issues still matter."],
  ["For f(x)=x² on x≥2, where is the convex constrained minimum?","x=2, giving 4; the unconstrained minimizer 0 is infeasible."],
  ["Why can nonconvex models require multiple starting points?","Different starts may reach different local candidates; compare objectives and validation results."],
  "convex: f(tx+(1−t)y)≤tf(x)+(1−t)f(y), 0≤t≤1",[check("(3-3)**2",0)]);
C("calc-robust-optimum",9,"Optimization under uncertainty","Model optimum versus robust choice",
  "A robust decision remains acceptable across plausible model errors or scenarios.",
  "It reduces dependence on a single precisely estimated optimum.",
  "Evaluate objective values and constraints across plausible parameters, not only their best-fit values.",
  "The highest narrow hilltop can be riskier than a slightly lower broad plateau.",
  ["Estimated profit is 10q−q² with optimum q=5. If the true coefficient is 8, profit at q=5?","8×5−25=15; the true optimum q=4 gives 16."],
  ["A precisely computed optimum is treated as precisely known in reality. What is wrong?","Calculation precision does not remove uncertainty in demand, costs or constraints."],
  ["Under the true coefficient 8, how much less is profit at q=5 than at q=4?","1/16=6.25% less."],
  ["What should be varied in an optimization sensitivity check?","Parameters, constraints, costs, scenarios and estimation error relevant to the decision."],
  ["Why can a broad near-optimal region be useful?","Several feasible choices perform similarly, allowing practical buffers and lower implementation risk."],
  ["Should a robust choice ignore expected reward?","No. Compare the reward sacrificed with protection gained across credible scenarios."],
  "test f(q;θ) across plausible θ",[check("(16-15)/16",.0625)]);

// Band 10: integrated quantitative judgment.
P("prob-edge-forecast",10,"Forecast evaluation","Forecast probabilities and price",
  "A useful probability must be compared with the offered payout and costs.",
  "A high win chance alone cannot establish a positive-value trade or bet.",
  "For a €1 stake at decimal odds d, expected net profit is pd−1 before costs.",
  "Buying a likely win at too high a price can still be a bad deal.",
  ["An event has estimated chance 70%, and decimal payout is 1.3. Expected net ROI?","0.7×1.3−1=−0.09=−9%, before costs."],
  ["A 70% win chance is declared profitable regardless of payout. What is wrong?","The price can require a break-even chance above 70%."],
  ["What is break-even probability at decimal payout 1.3?","1/1.3≈76.92%, before costs."],
  ["What evidence supports using a model's probability in an EV calculation?","Calibration, suitable population, honest validation and uncertainty about the edge."],
  ["At chance 55% and payout 2.0, expected net ROI before costs?","0.55×2−1=10%."],
  ["Why can a positive estimated ROI still be a poor full-size allocation?","Edge uncertainty, dependence, downside, liquidity and costs can outweigh the estimated advantage."],
  "net ROI=p×decimal payout−1",[check(".7*1.3-1",-.09)]);
P("prob-outside-validation",10,"Forecast evaluation","Validation in the target setting",
  "A probability model should be tested on outcomes representative of its intended use.",
  "It catches forecasts that work only on historical winners or familiar conditions.",
  "Separate fitting and evaluation; preserve time order when future prediction is the task.",
  "A map tested in one city may not navigate another city's roads.",
  ["A model predicts 60% across 500 new comparable events; 250 succeed. Observed rate?","250/500=50%, 10 percentage points below 60%."],
  ["Training accuracy is presented as untouched future performance. What is wrong?","The model has already learned from those outcomes; the evaluation is optimistic."],
  ["Why can a random train/test split leak information in a time-dependent process?","Future-related observations or overlapping records can inform earlier predictions."],
  ["What should be inspected before trusting a new validation set?","Representativeness, duplicates, time leakage, missing cases and outcome definitions."],
  ["A model is calibrated for large-cap stocks. Is small-cap calibration guaranteed?","No. Liquidity, volatility and population differences require new validation."],
  ["How should a model be monitored after deployment?","Track calibration and relevant errors over time, including changing subgroups and regimes."],
  "",[check("250/500",.5)]);
P("prob-costly-positive",10,"Decision probabilities","False alarms and decision costs",
  "A posterior probability supports a decision only after error costs and benefits are specified.",
  "It separates accurate classification from useful action.",
  "Act when expected benefit exceeds expected cost, using the same posterior and net outcomes.",
  "A smoke alarm can deserve attention at a low fire chance because missing fire is costly.",
  ["A flagged order has 20% fraud probability. Reviewing costs €2 and would prevent €20 loss when fraud is present. Expected net benefit?","0.2×20−2=€2, assuming review always prevents that loss and adds no other cost."],
  ["Most flags are false, so every review is called worthless. What is wrong?","A minority of costly true cases can justify review; costs and benefits determine the decision."],
  ["Under those assumptions, what fraud probability breaks even?","2/20=10%."],
  ["What assumptions must the simple review calculation check?","Actual prevented loss, review effectiveness, legitimate-customer costs and the posterior's reliability."],
  ["Review prevents only half of fraud losses. Expected net benefit at 20%?","0.2×0.5×20−2=€0, break-even before other costs."],
  ["Why can two businesses rationally use different alert thresholds?","Their loss sizes, review costs and error consequences differ."],
  "expected net benefit=p×prevented loss−action cost",[check(".2*20-2",2)]);
